window.SITE_HERITAGE = [{"id":"sarmizegetusa-regia","name":"Sarmizegetusa Regia","category":{"ro":"Sit arheologic UNESCO","en":"UNESCO archaeological site"},"area":"Munții Orăștiei","townId":"orastioara-de-sus","coords":[45.6219,23.3093],"hasReviews":true,"images":["images/sarmizegetusa-regia-sanctuar.jpg"],"photoCredit":{"author":"Eliza Palos","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sarmizegetusa_Regia-Sanctuarul_mare_circular_(Zona_sacr%C4%83).jpg"},"ro":{"tagline":"Capitala regatului dac, pe un vârf la 1.200 m altitudine — patrimoniu mondial UNESCO din 1999.","description":["Sarmizegetusa Regia a fost centrul politic și religios al regatului dac timp de peste un secol și jumătate, ajungând la apogeu sub Decebal. Fortificația, construită în tehnica „murus dacicus” pe cinci terase, ocupă aproape 30.000 m².","Zona sacră din apropiere cuprinde temple rectangulare și celebrul sanctuar circular — un „calendar” din stâlpi de lemn și piatră, una dintre cele mai discutate construcții din arheologia românească."],"facts":[{"label":"Statut","value":"Patrimoniu mondial UNESCO din 1999"},{"label":"Altitudine","value":"cca. 1.200 m"},{"label":"Tehnică de construcție","value":"Murus dacicus (blocuri de piatră fasonate)"}]},"en":{"tagline":"The capital of the Dacian kingdom, on a 1,200 m summit — UNESCO World Heritage since 1999.","description":["Sarmizegetusa Regia was the political and religious centre of the Dacian kingdom for over a century and a half, reaching its peak under Decebalus. The fortress, built in the “murus dacicus” technique across five terraces, covers almost 30,000 m².","The nearby sacred area holds rectangular temples and the famous circular sanctuary — a wood-and-stone “calendar”, one of the most discussed structures in Romanian archaeology."],"facts":[{"label":"Status","value":"UNESCO World Heritage since 1999"},{"label":"Altitude","value":"approx. 1,200 m"},{"label":"Construction technique","value":"Murus dacicus (fitted stone blocks)"}]}},{"id":"biserica-densus","name":"Biserica din Densuș","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Țara Hațegului","townId":"densus","coords":[45.5819,22.8047],"hasReviews":true,"images":["images/densus-biserica.jpg"],"photoCredit":{"author":"Bodor Istvan","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Biserica_Sf%C3%A2ntul_Nicolae_din_Densu%C8%99_2.jpg"},"ro":{"tagline":"Una dintre cele mai vechi biserici de piatră din România aflate încă în uz, ridicată din materiale romane refolosite.","description":["Datată în jurul secolelor XII–XIII, biserica din Densuș a fost construită în bună parte din piatră și elemente arhitecturale romane recuperate din ruinele apropiate. Forma sa neobișnuită și vechimea o fac unul dintre cele mai vizitate monumente din Țara Hațegului."],"facts":[{"label":"Datare","value":"Cca. secolele XII–XIII"},{"label":"Particularitate","value":"Construită din piatră romană refolosită"}]},"en":{"name":"Densuș Church","tagline":"One of the oldest stone churches in Romania still in use, built from reused Roman materials.","description":["Dated to around the 12th–13th centuries, the Densuș church was largely built from Roman stone and architectural elements recovered from nearby ruins. Its unusual shape and age make it one of the most visited monuments in Țara Hațegului."],"facts":[{"label":"Dating","value":"Approx. 12th–13th centuries"},{"label":"Distinctive feature","value":"Built from reused Roman stone"}]}},{"id":"manastirea-prislop","name":"Mănăstirea Prislop","category":{"ro":"Mănăstire","en":"Monastery"},"area":"Silvașu de Sus, Țara Hațegului","townId":"hateg","coords":[45.6317,22.8503],"hasReviews":true,"images":["images/prislop-manastire.jpg"],"photoCredit":{"author":"Tomoniu N. Nicolae","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Biserica_%22Sf._Treime%22_a_M%C4%83n%C4%83stirii_Prislop_img-0690.jpg"},"ro":{"tagline":"Ctitorie din 1564, loc de pelerinaj legat de părintele Arsenie Boca.","description":["Biserica actuală a fost ridicată în 1564 de Domnița Zamfira. Mănăstirea a devenit un important loc de pelerinaj după ce părintele Arsenie Boca a fost stareț aici din 1948 până la moartea sa, în 1989 — este înmormântat în incinta mănăstirii, care primește anual mii de pelerini."],"facts":[{"label":"Ctitorire biserică","value":"1564, de Domnița Zamfira"},{"label":"Legătură","value":"Mormântul părintelui Arsenie Boca (stareț 1948–1989)"}]},"en":{"name":"Prislop Monastery","tagline":"Founded in 1564, a pilgrimage site linked to Father Arsenie Boca.","description":["The current church was built in 1564 by Princess Zamfira. The monastery became a major pilgrimage site after Father Arsenie Boca served as its abbot from 1948 until his death in 1989 — he is buried on the monastery grounds, which receive thousands of pilgrims every year."],"facts":[{"label":"Church founded","value":"1564, by Princess Zamfira"},{"label":"Connection","value":"Grave of Father Arsenie Boca (abbot 1948–1989)"}]}},{"id":"muzeul-mineritului-petrosani","name":"Muzeul Mineritului din Petroșani","category":{"ro":"Muzeu","en":"Museum"},"area":"Petroșani","townId":"petrosani","coords":[45.4166,23.3733],"hasReviews":true,"season":"tot-anul","images":["images/muzeul-mineritului-petrosani.jpg"],"photoCredit":{"author":"Strainu","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Muzeul_Mineritului_(2).JPG"},"ro":{"tagline":"Singurul muzeu din România dedicat exclusiv tehnicii miniere a cărbunelui.","description":["Înființat în 1961, muzeul funcționează din 1966 într-o clădire din 1920, fostă locuință pentru angajați, azi monument istoric. Colecția, de circa 1.500 de piese (utilaje, unelte, documente, echipament de mină), a fost redeschisă publicului în 2021 după restaurare."],"facts":[{"label":"Înființat","value":"1961"},{"label":"Colecție","value":"cca. 1.500 de piese legate de minerit"},{"label":"Redeschis","value":"2021, după restaurare"}]},"en":{"name":"Mining Museum, Petroșani","tagline":"The only museum in Romania dedicated exclusively to coal-mining technology.","description":["Founded in 1961, the museum has operated since 1966 in a 1920 building, formerly staff housing, now a historic monument. The collection of about 1,500 items (equipment, tools, documents, mining gear) reopened to the public in 2021 after restoration."],"facts":[{"label":"Founded","value":"1961"},{"label":"Collection","value":"approx. 1,500 mining-related items"},{"label":"Reopened","value":"2021, after restoration"}]}},{"id":"mina-petrila","name":"Mina Petrila (Planeta Petrila)","category":{"ro":"Ansamblu industrial istoric","en":"Historic industrial site"},"area":"Petrila","townId":"petrila","hasReviews":true,"season":"tot-anul","images":["images/mina-petrila.jpg"],"photoCredit":{"author":"Loraine","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Petrila_view.jpg"},"ro":{"tagline":"Cea mai veche exploatare din Valea Jiului, azi transformată într-un muzeu în aer liber.","description":["Mina Petrila și-a încheiat activitatea în 2015, după peste un secol de exploatare a cărbunelui, și a fost clasată în același an ca monument istoric de valoare națională excepțională. Ansamblul, cumpărat de Consiliul Județean Hunedoara în 2022, cuprinde atelierele mecanice, clădirea compresoarelor, termocentrala cu șornul ei caracteristic, Puțul Nou cu schip și Puțul Central, pe o suprafață de aproape 164.000 mp.","Cunoscută drept „Planeta Petrila”, fosta mină găzduiește tururi ghidate, proiecții de film și festivalul internațional Opera Nights, într-un proiect de regenerare urbană finanțat prin PNRR care urmărește introducerea ei permanentă în circuitul turistic."],"facts":[{"label":"Închidere/clasare monument","value":"2015"},{"label":"Suprafață ansamblu","value":"~163.855 mp"},{"label":"Ce se vede","value":"atelierele mecanice, termocentrala, Puțul Nou și Puțul Central"},{"label":"Vizitare","value":"tururi ghidate; festivalul Opera Nights"}]},"en":{"name":"Petrila Mine (Planeta Petrila)","tagline":"The oldest mine in the Jiu Valley, now turned into an open-air museum.","description":["Petrila Mine closed in 2015, after more than a century of coal extraction, and was listed the same year as a historic monument of exceptional national value. The complex, bought by Hunedoara County Council in 2022, includes the mechanical workshops, the compressor building, the power plant with its distinctive chimney, the New Shaft with its cage lift and the Central Shaft, covering nearly 164,000 sq m.","Known as “Planet Petrila”, the former mine now hosts guided tours, film screenings and the international Opera Nights festival, part of a PNRR-funded urban regeneration project aiming to bring it permanently into the tourist circuit."],"facts":[{"label":"Closed / listed as monument","value":"2015"},{"label":"Site area","value":"~163,855 sq m"},{"label":"What to see","value":"mechanical workshops, power plant, New Shaft and Central Shaft"},{"label":"Visiting","value":"guided tours; Opera Nights festival"}]}},{"id":"crucea-eroilor-lupeni","name":"Crucea Eroilor de pe Muntele Straja","category":{"ro":"Monument","en":"Memorial"},"area":"Lupeni","townId":"lupeni","hasReviews":true,"season":"tot-anul","images":["images/crucea-eroilor-straja.jpg"],"photoCredit":{"author":"Bogdan Muraru","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cruz_Straja.jpg"},"ro":{"tagline":"Cruce de oțel înaltă de 18,6 m, la 1.485 m pe Muntele Straja, în memoria celor 800 de militari români căzuți în 1916 în luptele din Defileul Jiului.","description":["Crucea Eroilor de pe Muntele Straja, deasupra Lupeniului, este un monument comemorativ dedicat celor 800 de militari români care au căzut în toamna anului 1916, în luptele din Defileul Jiului, în Primul Război Mondial. Crucea, din oțel, are 18,6 m și se află la altitudinea de 1.485 m. A fost sfințită pe 30 octombrie 1996 de starețul Mănăstirii Lainici, Ioachim Pârvulescu, și a fost ridicată din donații private, în mare parte ale omului de afaceri Emil Ilie Părău. Lângă ea a fost construit, începând din 1999, Schitul Straja.","Se ajunge din Lupeni pe o șosea asfaltată de circa 8 km, până în stațiunea Straja. Din 2000, în Vinerea Mare se organizează anual o procesiune asemănătoare Drumului Crucii.","Nu trebuie confundată cu memorialul minerilor morți în explozia de gaz metan de la Mina Aurelia, pe 27 aprilie 1922 — cea mai gravă tragedie din istoria mineritului din Valea Jiului, soldată cu 82 de morți, 62 de văduve și 124 de orfani, după care regele Ferdinand I a venit la Lupeni. Monumentul de piatră dedicat lor se află în cimitirul din Lupeni, unde la aniversarea tragediei, pe 27 aprilie, au loc slujbe de pomenire."],"facts":[{"label":"Comemorează","value":"cei 800 de militari români căzuți în 1916 în Defileul Jiului"},{"label":"Dimensiuni","value":"cruce de oțel de 18,6 m, la 1.485 m altitudine"},{"label":"Sfințire","value":"30 octombrie 1996"},{"label":"Acces","value":"șosea asfaltată de circa 8 km din Lupeni, până în stațiunea Straja"}]},"en":{"name":"Heroes' Cross on Mount Straja","tagline":"An 18.6 m steel cross at 1,485 m on Mount Straja, honouring the 800 Romanian soldiers who fell in 1916 in the battles of the Jiu Gorge.","description":["The Heroes' Cross on Mount Straja, above Lupeni, is a memorial to the 800 Romanian soldiers who fell in the autumn of 1916 in the battles of the Jiu Gorge, during the First World War. The steel cross is 18.6 m tall and stands at an altitude of 1,485 m. It was consecrated on 30 October 1996 by the abbot of Lainici Monastery, Ioachim Pârvulescu, and was built from private donations, mostly from businessman Emil Ilie Părău. The Straja hermitage (Schitul Straja) was built next to it from 1999 onwards.","It is reached from Lupeni on a paved road of about 8 km, up to the Straja resort. Since 2000, a procession similar to the Way of the Cross has been held here every year on Good Friday.","It should not be confused with the memorial to the miners killed in the methane explosion at Aurelia Mine on 27 April 1922 — the worst disaster in the Jiu Valley's mining history, which left 82 dead, 62 widows and 124 orphans, and after which King Ferdinand I came to Lupeni. Their stone monument stands in the Lupeni cemetery, where memorial services are held on the anniversary, 27 April."],"facts":[{"label":"Commemorates","value":"the 800 Romanian soldiers who fell in 1916 in the Jiu Gorge"},{"label":"Size","value":"18.6 m steel cross, at 1,485 m altitude"},{"label":"Consecrated","value":"30 October 1996"},{"label":"Access","value":"paved road of about 8 km from Lupeni, up to the Straja resort"}]}},{"id":"aleea-gimnastelor","name":"Aleea Gimnastelor","category":{"ro":"Alee comemorativă","en":"Memorial walk"},"area":"Deva","townId":"deva","hasReviews":true,"season":"tot-anul","images":["images/aleea-gimnastelor-deva.jpg"],"photoCredit":{"author":"Leontin l","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Deva_2019_(8).jpg"},"ro":{"tagline":"Alee cu 15 busturi de bronz, inaugurată în 2008 la poalele Cetății Deva, dedicată gimnastelor și antrenorilor care au făcut din Deva un centru mondial al gimnasticii.","description":["Aleea Gimnastelor a fost inaugurată în 2008 la baza Cetății Deva, chiar în fața sălii unde se antrenează lotul național feminin de gimnastică, lângă stația de plecare a telecabinei. Aleea are 15 busturi de bronz de circa 42-43 cm, realizate de artistul plastic Ioan Șeu, turnate la o fabrică din București și așezate pe socluri de granit înalte de 1,80 m.","Ansamblul cuprinde patru busturi de antrenori — cuplurile Marta și Bela Karolyi, respectiv Mariana Bitang și Octavian Bellu — și 11 busturi de gimnaste, printre care Nadia Comăneci, Lavinia Agache, Ecaterina Szabo, Daniela Silivaș, Monica Roșu și Andreea Răducan. Aleea marchează palmaresul școlii de gimnastică de la Deva, unde s-a mutat lotul național în 1978, de la Onești.","Pe 22 aprilie 2026, Consiliul Local Deva a aprobat amplasarea a încă trei busturi, din marmură — ale gimnastelor Sandra Izbașa și Cătălina Ponor și al antrenorului Nicolae Forminte —, care vor completa ansamblul. Până la începutul lui octombrie 2026 nu fusese anunțată o dată pentru dezvelirea lor."],"facts":[{"label":"Inaugurare","value":"2008"},{"label":"Compoziție","value":"15 busturi de bronz (4 antrenori + 11 gimnaste)"},{"label":"Antrenori comemorați","value":"Marta și Bela Karolyi, Mariana Bitang și Octavian Bellu"},{"label":"Amplasare","value":"la poalele Cetății Deva, lângă stația telecabinei"}]},"en":{"name":"Gymnasts' Walk","tagline":"A row of 15 bronze busts, unveiled in 2008 at the foot of Deva Citadel, honouring the gymnasts and coaches who made Deva a world centre of gymnastics.","description":["Aleea Gimnastelor (“the gymnasts' walk”) was unveiled in 2008 at the base of Deva Citadel, right in front of the hall where the national women's gymnastics team trains, next to the cable car's lower station. The walk has 15 bronze busts about 42-43 cm tall, made by the artist Ioan Șeu, cast at a foundry in Bucharest and set on 1.80 m granite pedestals.","The ensemble includes four busts of coaches — the couples Marta and Bela Karolyi, and Mariana Bitang and Octavian Bellu — and 11 busts of gymnasts, including Nadia Comăneci, Lavinia Agache, Ecaterina Szabo, Daniela Silivaș, Monica Roșu and Andreea Răducan. The walk marks the record of Deva's gymnastics school, where the national team moved in 1978, from Onești.","On 22 April 2026, Deva Local Council approved three more busts, in marble — of gymnasts Sandra Izbașa and Cătălina Ponor and of coach Nicolae Forminte — which will be added to the ensemble. As of early October 2026, no date had been announced for their unveiling."],"facts":[{"label":"Unveiled","value":"2008"},{"label":"Composition","value":"15 bronze busts (4 coaches + 11 gymnasts)"},{"label":"Coaches honoured","value":"Marta and Bela Karolyi, Mariana Bitang and Octavian Bellu"},{"label":"Location","value":"at the foot of Deva Citadel, by the cable car station"}]}},{"id":"muzeul-civilizatiei-dacice-si-romane-deva","name":"Muzeul Civilizației Dacice și Romane — Magna Curia","category":{"ro":"Muzeu","en":"Museum"},"area":"Deva","townId":"deva","hasReviews":true,"season":"tot-anul","images":["images/muzeul-civilizatiei-dacice-deva.jpg"],"photoCredit":{"author":"Andrei kokelburg","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Deva_Magna_curia_(1).jpg"},"ro":{"tagline":"Palatul baroc Magna Curia, în centrul Devei, găzduiește colecțiile de istorie ale Muzeului Civilizației Dacice și Romane și un lapidariu cu peste o sută de piese arheologice.","description":["Magna Curia este un monument istoric de categorie A, ridicat inițial ca reședință a principelui Transilvaniei Gabriel Bethlen și a soției sale Susana, care au modificat substanțial clădirea între 1614 și 1618. La mijlocul secolului al XVIII-lea, guvernatorul Transilvaniei Ioan Haller și soția sa, Sofia Dániel, au transformat-o în palat baroc, înfățișare păstrată până azi. Clădirea se află pe Bulevardul 1 Decembrie nr. 39.","Aici sunt expuse secțiile de istorie și numismatică ale Muzeului Civilizației Dacice și Romane — piese preistorice, dacice, romane și medievale timpurii, alături de colecții de etnografie și de științe naturale (botanică, paleontologie, mineralogie). În spatele palatului se află Lapidariul, o structură de sticlă cu peste o sută de piese arheologice masive, organizate în cinci săli tematice."],"facts":[{"label":"Adresă","value":"Bd. 1 Decembrie nr. 39, Deva"},{"label":"Clădire","value":"Palatul Magna Curia (Bethlen), monument istoric categoria A"},{"label":"Transformare barocă","value":"mijlocul secolului XVIII, guvernatorul Ioan Haller"},{"label":"Colecții","value":"arheologie, etnografie, numismatică, științe naturale; Lapidariul (100+ piese)"}]},"en":{"name":"Museum of Dacian and Roman Civilisation — Magna Curia","tagline":"The baroque Magna Curia palace, in central Deva, houses the history collections of the Museum of Dacian and Roman Civilisation and a lapidarium with over a hundred archaeological pieces.","description":["Magna Curia is a category A historic monument, originally built as a residence for Transylvanian prince Gabriel Bethlen and his wife Susana, who substantially altered the building between 1614 and 1618. In the mid-18th century, Transylvania's governor Ioan Haller and his wife, Sofia Dániel, turned it into a baroque palace, an appearance preserved to this day. The building stands at 39, 1 Decembrie Boulevard.","It houses the history and numismatics sections of the Museum of Dacian and Roman Civilisation — prehistoric, Dacian, Roman and early medieval pieces, alongside ethnography and natural sciences collections (botany, palaeontology, mineralogy). Behind the palace stands the Lapidarium, a glass structure with over a hundred massive archaeological pieces, arranged in five themed rooms."],"facts":[{"label":"Address","value":"39, 1 Decembrie Blvd., Deva"},{"label":"Building","value":"Magna Curia (Bethlen) Palace, category A historic monument"},{"label":"Baroque conversion","value":"mid-18th century, governor Ioan Haller"},{"label":"Collections","value":"archaeology, ethnography, numismatics, natural sciences; the Lapidarium (100+ pieces)"}]}},{"id":"muzeul-etnografie-orastie","name":"Muzeul de Etnografie și Artă Populară Orăștie","category":{"ro":"Muzeu","en":"Museum"},"area":"Orăștie","townId":"orastie","hasReviews":true,"season":"tot-anul","images":["images/muzeul-etnografie-orastie.jpg"],"photoCredit":{"author":"Mihai Stancu","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Muzeul_de_Etnografie_si_Arta_Populara_Orastie.jpg"},"ro":{"tagline":"Colecție de etnografie și artă populară de aproape 8.000 de piese, într-o clădire-monument istoric din centrul orașului.","description":["Muzeul a fost înființat în 1952, din inițiativa unui grup de entuziaști locali care au strâns primele colecții. În 1974, profilul instituției s-a reorientat spre artă populară, iar din 1991 funcționează ca secție a Muzeului Civilizației Dacice și Romane Deva. Clădirea în care funcționează, din prima jumătate a secolului XX, este ea însăși monument istoric.","Colecția, de circa 8.000 de bunuri culturale, cuprinde piese de etnografie și artă populară (unelte, ceramică, costume, icoane pe lemn și sticlă), alături de fonduri de istorie, arheologie și numismatică, plus o bibliotecă documentară de aproximativ 5.000 de volume."],"facts":[{"label":"Adresă","value":"Piața Aurel Vlaicu nr. 1, Orăștie"},{"label":"Program","value":"Mar–Dum 10:00–18:00 (mar–oct), 9:00–17:00 (nov–feb); luni închis"},{"label":"Înființat","value":"1952"},{"label":"Colecție","value":"~8.000 de piese (etnografie, istorie, arheologie, numismatică)"}]},"en":{"name":"Museum of Ethnography and Folk Art, Orăștie","tagline":"A collection of nearly 8,000 ethnographic and folk-art items, in a historic-monument building downtown.","description":["The museum was founded in 1952, on the initiative of a group of local enthusiasts who assembled its first collections. In 1974 its focus shifted toward folk art, and since 1991 it has operated as a section of the Museum of Dacian and Roman Civilisation in Deva. The building it occupies, dating from the first half of the 20th century, is itself a listed historic monument.","The collection, of about 8,000 cultural items, includes ethnographic and folk-art pieces (tools, ceramics, costumes, icons on wood and glass), alongside history, archaeology and numismatics holdings, plus a documentary library of roughly 5,000 volumes."],"facts":[{"label":"Address","value":"Piața Aurel Vlaicu no. 1, Orăștie"},{"label":"Hours","value":"Tue–Sun 10:00–18:00 (Mar–Oct), 9:00–17:00 (Nov–Feb); closed Mondays"},{"label":"Founded","value":"1952"},{"label":"Collection","value":"~8,000 items (ethnography, history, archaeology, numismatics)"}]}},{"id":"cetatea-medievala-orastie","name":"Cetatea medievală a Orăștiei","category":{"ro":"Cetate medievală","en":"Medieval fortress"},"area":"Orăștie","townId":"orastie","hasReviews":true,"season":"tot-anul","images":["images/orastie-cetate.jpg"],"photoCredit":{"author":"Roamata","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:Cetatea_orastie.JPG"},"ro":{"tagline":"Fortificație săsească din secolul XII, redeschisă publicului în 2024 după trei ani de restaurare.","description":["Cetatea medievală a Orăștiei datează din secolul XII, de la sosirea primilor coloniști sași, și a servit drept reședință a unor grafi (conducători) ai comunității săsești locale. De-a lungul secolelor a trecut prin numeroase asedii, incendii și refaceri: a fost prădată de tătari la mijlocul secolului XIII și devastată de turci la începutul secolului XV și din nou la mijlocul secolului XVII.","Restaurată între toamna anului 2021 și septembrie 2024, cu fonduri europene, cetatea și-a redeschis porțile chiar în anul în care Orăștie a marcat 800 de ani de la prima atestare documentară. În incinta ei se află o rotondă din piatră veche de aproape 1.000 de ani — una dintre cele mai vechi construcții de acest tip din România —, două biserici istorice (reformată și evanghelică) și un muzeu dedicat civilizației dacice, amenajat într-o clădire din secolul XIX, fostul spital al orașului."],"facts":[{"label":"Vechime","value":"secolul XII (cca. 8 secole)"},{"label":"Restaurare","value":"2021–2024 (3 ani, fonduri europene)"},{"label":"Redeschidere","value":"septembrie 2024, la 800 de ani de atestare documentară a Orăștiei"},{"label":"Ce cuprinde","value":"rotondă de cca. 1.000 de ani, biserica reformată, biserica evanghelică, muzeu dacic"}]},"en":{"name":"Orăștie Medieval Citadel","tagline":"A 12th-century Saxon fortification, reopened to the public in 2024 after three years of restoration.","description":["The medieval fortress of Orăștie dates from the 12th century, from the arrival of the first Saxon colonists, and served as the seat of local Saxon community leaders (“graefs”). Over the centuries it went through numerous sieges, fires and rebuildings: it was plundered by the Tatars in the mid-13th century and devastated by the Ottomans in the early 15th century and again in the mid-17th century.","Restored between autumn 2021 and September 2024 with EU funding, the fortress reopened its gates in the very year Orăștie marked 800 years since its first documentary mention. Inside stands a nearly 1,000-year-old stone rotunda — one of the oldest structures of its kind in Romania —, two historic churches (Reformed and Evangelical) and a museum dedicated to Dacian civilisation, set up in a 19th-century building that once served as the town's hospital."],"facts":[{"label":"Age","value":"12th century (approx. 8 centuries)"},{"label":"Restoration","value":"2021–2024 (3 years, EU funding)"},{"label":"Reopened","value":"September 2024, marking 800 years since Orăștie's first documentary mention"},{"label":"What to see","value":"~1,000-year-old rotunda, Reformed church, Evangelical church, Dacian museum"}]}},{"id":"casa-memoriala-aurel-vlaicu","name":"Complexul Memorial „Aurel Vlaicu”","category":{"ro":"Casă memorială","en":"Memorial house"},"area":"Aurel Vlaicu","townId":"geoagiu","hasReviews":true,"season":"tot-anul","images":["images/casa-memoriala-aurel-vlaicu.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Casa_natal%C4%83_Aurel_Vlaicu.JPG"},"ro":{"tagline":"Casa natală și muzeul dedicat inventatorului și aviatorului Aurel Vlaicu, în satul de lângă Orăștie care îi poartă azi numele.","description":["Satul Binținți, lângă Orăștie (comuna Geoagiu), a fost redenumit Aurel Vlaicu în cinstea inventatorului și aviatorului născut aici. Complexul memorial cuprinde trei componente: casa memorială, deschisă publicului în 1952, muzeul memorial amenajat lângă casă în 1982 și un bust-monument ridicat în 1933.","Expoziția muzeului include machete ale aparatelor de zbor construite de Vlaicu, unelte și obiecte personale, casca și echipamentul purtate în ultimul zbor, piese recuperate din avionul în care s-a prăbușit la 13 septembrie 1913, precum și scrisori, ziare de epocă și distincții internaționale primite de-a lungul carierei sale."],"facts":[{"label":"Adresă","value":"str. Aurel Vlaicu nr. 177, satul Aurel Vlaicu, comuna Geoagiu"},{"label":"Program","value":"Mar–Dum 9:00–17:00 (iarna), 10:00–18:00 (vara); luni închis"},{"label":"Componente","value":"casa memorială (1952), muzeul memorial (1982), bust-monument (1933)"},{"label":"Ce se vede","value":"machete de aparate de zbor, echipament, piese din avionul accidentat în 1913"}]},"en":{"name":"“Aurel Vlaicu” Memorial Complex","tagline":"The birthplace and museum of inventor and aviator Aurel Vlaicu, in the village near Orăștie that now bears his name.","description":["The village of Binținți, near Orăștie (Geoagiu commune), was renamed Aurel Vlaicu in honour of the inventor and aviator born there. The memorial complex has three parts: the memorial house, opened to the public in 1952, the memorial museum built next to it in 1982, and a bust-monument erected in 1933.","The museum's exhibits include models of the aircraft Vlaicu built, tools and personal belongings, the helmet and gear worn on his final flight, pieces recovered from the aircraft in which he crashed on 13 September 1913, as well as letters, period newspapers and international awards received during his career."],"facts":[{"label":"Address","value":"Str. Aurel Vlaicu no. 177, Aurel Vlaicu village, Geoagiu commune"},{"label":"Hours","value":"Tue–Sun 9:00–17:00 (winter), 10:00–18:00 (summer); closed Mondays"},{"label":"Components","value":"memorial house (1952), memorial museum (1982), bust-monument (1933)"},{"label":"What to see","value":"aircraft models, gear, pieces from the aircraft that crashed in 1913"}]}},{"id":"muzeul-aurului-brad","name":"Muzeul Aurului din Brad","category":{"ro":"Muzeu","en":"Museum"},"area":"Brad","townId":"brad","hasReviews":true,"season":"tot-anul","images":["images/muzeul-aurului-brad.jpg"],"photoCredit":{"author":"Andrei Stroe","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Brad_gold_museum.JPG"},"ro":{"tagline":"Cea mai mare colecție de aur nativ din Europa, cu exponate neprelucrate de niciun bijutier.","description":["Muzeul Aurului din Brad funcționează din 1896, pornind de la colecțiile de minerale și unelte miniere ale societăților care exploatau zăcămintele aurifere din Munții Metaliferi. Astăzi adăpostește peste 2.000 de exponate — minerale și piese de aur nativ, niciuna prelucrată de vreun bijutier —, considerată una dintre cele mai importante colecții de acest fel din lume.","Printre piesele cele mai cunoscute, vizitatorii au dat nume proprii unor formațiuni native, precum „Balerina”, un cristal cu douăsprezece fețe unic în lume, sau șopârlele de aur, dintre care una a fost asigurată cu 500.000 de euro la un transport pentru expunere într-un muzeu german. Muzeul se află pe strada Independenței nr. 3 și e deschis zilnic."],"facts":[{"label":"Înființat","value":"1896"},{"label":"Colecție","value":"peste 2.000 de exponate (minerale și aur nativ)"},{"label":"Piesă unică","value":"„Balerina” — cristal de aur cu 12 fețe, unic în lume"},{"label":"Program","value":"zilnic, 9:00–17:00"}]},"en":{"name":"Gold Museum, Brad","tagline":"The largest collection of native gold in Europe, with pieces untouched by any jeweller.","description":["The Gold Museum in Brad has operated since 1896, growing out of the mineral and mining-tool collections of the companies that worked the gold deposits of the Metaliferi Mountains. Today it holds over 2,000 exhibits — minerals and native gold pieces, none of them reworked by a jeweller — regarded as one of the most important collections of its kind in the world.","Among its best-known pieces, visitors have given proper names to native gold formations, such as “The Ballerina”, a twelve-faced crystal unique in the world, and the gold “lizards”, one of which was insured for €500,000 during transport for display at a German museum. The museum stands on Independenței Street no. 3 and is open daily."],"facts":[{"label":"Founded","value":"1896"},{"label":"Collection","value":"over 2,000 exhibits (minerals and native gold)"},{"label":"Unique piece","value":"“The Ballerina” — a 12-faced gold crystal, unique in the world"},{"label":"Hours","value":"daily, 9:00 AM-5:00 PM"}]}},{"id":"treptele-romane-ruda-brad","name":"Treptele Romane (Ruda-Brad)","category":{"ro":"Sit arheologic minier","en":"Archaeological mining site"},"area":"Brad","townId":"brad","hasReviews":true,"season":"tot-anul","images":["images/placeholder.svg"],"ro":{"tagline":"Una dintre puținele galerii miniere romane păstrate în Munții Apuseni, săpată acum aproape 2.000 de ani.","description":["Treptele Romane este o galerie minieră săpată în stâncă la marginea satului Ruda, lângă Brad, în secolele II–III d.Hr., pentru extragerea aurului din zăcămintele Munților Metaliferi. Galeria, lungă de circa 200 de metri, își ia numele de la treptele tăiate în piatră la capătul tunelului săpat manual, cu târnăcopul, de mineri din perioada ocupației romane a Daciei.","Zona a fost exploatată aurifer încă din perioada dacică și a rămas în folosință secole la rând, fiind una dintre puținele mărturii vizibile ale tehnicii miniere romane din Dacia. Din motive de siguranță, intrarea în galerie este momentan închisă cu o ușă metalică, iar vizitatorii pot vedea doar pavilionul construit la intrare; autoritățile locale au în plan amenajarea zonei pentru vizitare."],"facts":[{"label":"Perioadă","value":"secolele II–III d.Hr. (epoca romană)"},{"label":"Lungime galerie","value":"~200 m"},{"label":"Localizare","value":"satul Ruda, lângă Brad"},{"label":"Acces","value":"doar pavilionul de la intrare — galeria e închisă publicului din motive de siguranță"}]},"en":{"name":"Roman Steps (Ruda-Brad)","tagline":"One of the few Roman-era mining galleries preserved in the Apuseni Mountains, dug nearly 2,000 years ago.","description":["Treptele Romane (“the Roman Steps”) is a mining gallery cut into the rock at the edge of Ruda village, near Brad, in the 2nd-3rd centuries AD, to extract gold from the deposits of the Metaliferi Mountains. The gallery, about 200 metres long, takes its name from the steps cut into stone at the end of the tunnel, dug by hand with pickaxes by miners during the Roman occupation of Dacia.","The area had been worked for gold since Dacian times and stayed in use for centuries afterwards, making it one of the few visible traces of Roman mining technique in Dacia. For safety reasons, the gallery entrance is currently closed with a metal door, and visitors can only see the pavilion built at the entrance; local authorities plan to open the area up for visiting."],"facts":[{"label":"Period","value":"2nd-3rd century AD (Roman era)"},{"label":"Gallery length","value":"~200 m"},{"label":"Location","value":"Ruda village, near Brad"},{"label":"Access","value":"entrance pavilion only — the gallery is closed to the public for safety reasons"}]}},{"id":"biserica-criscior","name":"Biserica „Adormirea Maicii Domnului” din Crișcior","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Crișcior","townId":"criscior","hasReviews":true,"season":"tot-anul","images":["images/biserica-criscior.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_%E2%80%9EAdormirea_Maicii_Domnului%E2%80%9D_din_Cri%C8%99cior.JPG"},"ro":{"tagline":"Biserică din secolele XIV–XV, ctitorită de voievodul Bâlea, cu picturi murale bizantine unice în zonă.","description":["Biserica „Adormirea Maicii Domnului” din Crișcior, la câțiva kilometri de Brad, a fost ridicată în secolele XIV–XV, din piatră, pe locul unei biserici de lemn mai vechi, cu turn-clopotniță pe latura de vest. Ctitori au fost voievodul local Bâlea și soția sa, Vișa, atestați documentar în 1404.","În interior s-au păstrat picturi murale din secolul al XV-lea, printre cele mai valoroase din zonă — un tablou votiv cu familia ctitorilor, scene din viața lui Iisus (Spălarea picioarelor, Cina cea de Taină, Drumul crucii) și chipurile unor sfinți militari și ale celor trei regi sfinți ai Ungariei. Biserica e clasată monument istoric de valoare națională, cu codul LMI HD-II-m-A-03303."],"facts":[{"label":"Construcție","value":"secolele XIV–XV"},{"label":"Ctitori","value":"voievodul Bâlea și soția sa, Vișa (atestați 1404)"},{"label":"Picturi murale","value":"secolul XV — tablou votiv, scene biblice, sfinți militari"},{"label":"Cod LMI","value":"HD-II-m-A-03303"}]},"en":{"name":"Church of the Dormition, Crișcior","tagline":"A 14th-15th century church founded by voivode Bâlea, with Byzantine murals unique to the area.","description":["The “Dormition of the Mother of God” church in Crișcior, a few kilometres from Brad, was built in stone in the 14th-15th centuries on the site of an older wooden church, with a bell tower on its western side. Its founders were the local voivode Bâlea and his wife Vișa, documented in 1404.","Inside, 15th-century murals have survived — among the most valuable in the area — including a votive painting of the founders' family, scenes from the life of Christ (the Washing of the Feet, the Last Supper, the Way of the Cross) and depictions of warrior saints and the three sainted kings of Hungary. The church is listed as a historic monument of national value, LMI code HD-II-m-A-03303."],"facts":[{"label":"Built","value":"14th-15th century"},{"label":"Founders","value":"voivode Bâlea and his wife Vișa (documented 1404)"},{"label":"Murals","value":"15th century — votive painting, biblical scenes, warrior saints"},{"label":"LMI code","value":"HD-II-m-A-03303"}]}},{"id":"castelul-corvinilor","name":"Castelul Corvinilor","category":{"ro":"Castel medieval","en":"Medieval castle"},"area":"Hunedoara","townId":"hunedoara","hasReviews":true,"season":"tot-anul","images":["images/castelul-corvinilor.jpg"],"photoCredit":{"author":"Giuseppe Milo","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Corvin_Castle_-_Hunedoara,_Romania_-_Travel_photography_(36729360851).jpg"},"ro":{"tagline":"Sala Cavalerilor, Sala Dietei și fântâna săpată de prizonieri turci — detaliile din spatele celui mai vizitat castel al țării.","description":["Ridicat de Iancu de Hunedoara după 1440 pe temeliile unei fortificații din secolul al XIV-lea și extins în stil renascentist de fiul său, regele Matia Corvin, între 1458 și 1480, castelul păstrează Sala Cavalerilor — sala de recepție cu bolți gotice, care poartă o inscripție în latină, „Hoc opus fecit fieri Magnificus Johannes de Hunyadi”, datată 1452 — și Sala Dietei, decorată cu medalioane pictate, printre care portretele domnitorilor Matei Basarab și Vasile Lupu.","Curtea interioară adăpostește fântâna despre care legenda spune că a fost săpată timp de 15 ani de trei prizonieri otomani, cărora li s-ar fi promis libertatea dacă găsesc apă; promisiunea nu ar fi fost respectată, iar inscripția rămasă pe pereții fântânii are o interpretare încă disputată de istorici. Castelul se vizitează tot anul; între 1 octombrie 2026 și 31 martie 2027 e în vigoare programul de iarnă (luni 12:00–17:00, marți–duminică 9:00–17:00), iar biletul de adult costă 55 de lei în 2026."],"facts":[{"label":"Construcție inițială","value":"După 1440, de Iancu de Hunedoara, pe o fortificație din secolul XIV"},{"label":"Extindere renascentistă","value":"1458–1480, sub regele Matia Corvin"},{"label":"Săli principale","value":"Sala Cavalerilor (inscripție din 1452), Sala Dietei"},{"label":"Program de iarnă","value":"1 oct. 2026 – 31 mar. 2027: luni 12:00–17:00, marți–duminică 9:00–17:00"},{"label":"Bilet adult (2026)","value":"55 lei"}]},"en":{"name":"Corvin Castle","tagline":"The Knights' Hall, the Diet Hall and a well dug by Turkish prisoners — the details behind Romania's most visited castle.","description":["Built by John Hunyadi (Iancu de Hunedoara) after 1440 on the foundations of a 14th-century fortification and expanded in Renaissance style by his son, King Matthias Corvinus, between 1458 and 1480, the castle preserves the Knights' Hall — a Gothic-vaulted reception room bearing a Latin inscription, “Hoc opus fecit fieri Magnificus Johannes de Hunyadi”, dated 1452 — and the Diet Hall, decorated with painted medallions, including portraits of Wallachian prince Matei Basarab and Moldavian prince Vasile Lupu.","The inner courtyard holds the well that, according to legend, three Ottoman prisoners spent 15 years digging in search of water after being promised freedom if they succeeded; the promise was reportedly broken, and an inscription said to remain on the well's walls has a meaning historians still dispute. The castle is open year-round; from 1 October 2026 to 31 March 2027 winter hours apply (Mondays 12:00–17:00, Tuesday–Sunday 9:00–17:00), and an adult ticket costs 55 lei in 2026."],"facts":[{"label":"Original construction","value":"After 1440, by John Hunyadi, on a 14th-century fortification"},{"label":"Renaissance expansion","value":"1458–1480, under King Matthias Corvinus"},{"label":"Main halls","value":"Knights' Hall (1452 inscription), Diet Hall"},{"label":"Winter hours","value":"1 Oct 2026 – 31 Mar 2027: Mon 12:00–17:00, Tue–Sun 9:00–17:00"},{"label":"Adult ticket (2026)","value":"55 lei"}]}},{"id":"furnalul-govajdia","name":"Furnalul de la Govăjdia","category":{"ro":"Ansamblu industrial istoric","en":"Historic industrial site"},"area":"Hunedoara","townId":"ghelari","hasReviews":false,"season":"tot-anul","images":["images/furnalul-govajdia.jpg"],"photoCredit":{"author":"RudolfHanzelik","license":"CC0 (domeniu public)","source":"https://commons.wikimedia.org/wiki/File:Blast_furnace_of_Govajdia.jpg"},"ro":{"tagline":"Furnal din 1810, primul cu flux continuu din Europa — vestigiu al tradiției siderurgice din care a crescut Hunedoara industrială.","description":["Construit între 1806 și 1810 lângă satul Govăjdia (comuna Ghelari, la circa 20 km de Hunedoara), furnalul a fost, la data punerii în funcțiune, primul furnal cu flux continuu din Europa și al doilea din lume, topind minereu de fier adus din Munții Poiana Ruscă. A funcționat până în 1924, fiind unul dintre punctele de plecare ale tradiției siderurgice care avea să facă din Hunedoara un centru metalurgic important.","Declarat monument de arhitectură industrială în anul 2000, ansamblul se află într-o stare avansată de degradare, în ciuda includerii, din 2021, într-un program național de restaurare. Rămâne totuși un reper de patrimoniu industrial unic în peisajul metalurgic românesc."],"facts":[{"label":"Construit","value":"1806–1810"},{"label":"Statut","value":"Monument de arhitectură industrială (Legea 5/2000), cod HD-II-m-A-03322"},{"label":"Particularitate tehnică","value":"Primul furnal cu flux continuu din Europa (al doilea din lume), la data punerii în funcțiune"},{"label":"Închidere","value":"1924"},{"label":"Locație","value":"Satul Govăjdia, comuna Ghelari, ~20 km de Hunedoara"}]},"en":{"name":"Govăjdia Blast Furnace","tagline":"A furnace from 1810, Europe's first continuous-flow blast furnace — a relic of the iron-making tradition that grew into industrial Hunedoara.","description":["Built between 1806 and 1810 near the village of Govăjdia (Ghelari commune, about 20 km from Hunedoara), the furnace was, when it went into operation, the first continuous-flow blast furnace in Europe and the second in the world, smelting iron ore brought from the Poiana Ruscă Mountains. It operated until 1924, marking one of the starting points of the iron-making tradition that would later turn Hunedoara into a major steel centre.","Listed as an industrial architecture monument in 2000, the complex is now in an advanced state of disrepair, despite being included, since 2021, in a national restoration programme. It remains, nonetheless, a unique piece of industrial heritage on the Romanian metallurgical landscape."],"facts":[{"label":"Built","value":"1806–1810"},{"label":"Status","value":"Industrial architecture monument (Law 5/2000), code HD-II-m-A-03322"},{"label":"Technical distinction","value":"First continuous-flow blast furnace in Europe (second in the world) at the time"},{"label":"Closed","value":"1924"},{"label":"Location","value":"Govăjdia village, Ghelari commune, ~20 km from Hunedoara"}]}},{"id":"castelul-bela-fay-simeria","name":"Castelul Béla Fáy","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Simeria","townId":"simeria","coords":[45.8569,23.011],"hasReviews":false,"season":"tot-anul","images":["images/castelul-bela-fay-simeria.jpg"],"photoCredit":{"author":"Seldon92","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Castelul_Bela_Fay.JPG"},"ro":{"tagline":"Conacul familiilor Gyulay, Kun, Fáy și Ocskay, în inima Arboretumului Simeria.","description":["Castelul, aflat pe strada Biscaria, în incinta Parcului Dendrologic Simeria, a aparținut de-a lungul secolelor XIX–XX mai multor familii nobiliare — Gyulay, Kun, Fáy și Ocskay — care au amenajat treptat și parcul din jur. Din 1918 proprietar a fost Béla Fáy, naturalist și membru al Academiei Maghiare de Științe.","Din 1954, clădirea găzduiește Stațiunea de Cercetare și Experimentare Silvică Simeria, care administrează și astăzi arboretumul din jur. Este inclus pe Lista Monumentelor Istorice din județul Hunedoara."],"facts":[{"label":"Datare","value":"secolul XIX"},{"label":"Proprietari istorici","value":"Gyulay, Kun, Fáy, Ocskay"},{"label":"Astăzi","value":"sediul Stațiunii de Cercetare și Experimentare Silvică Simeria"}]},"en":{"name":"Béla Fáy Manor","tagline":"The manor of the Gyulay, Kun, Fáy and Ocskay families, at the heart of the Simeria Arboretum.","description":["The manor, on Biscaria Street inside the Simeria Dendrological Park, belonged over the 19th–20th centuries to several noble families — Gyulay, Kun, Fáy and Ocskay — who gradually laid out the surrounding park. From 1918 its owner was Béla Fáy, a naturalist and member of the Hungarian Academy of Sciences.","Since 1954, the building has housed the Simeria Forest Research and Experimentation Station, which still manages the surrounding arboretum today. It is listed on Hunedoara county's List of Historic Monuments."],"facts":[{"label":"Dating","value":"19th century"},{"label":"Historic owners","value":"Gyulay, Kun, Fáy, Ocskay"},{"label":"Today","value":"home to the Simeria Forest Research and Experimentation Station"}]}},{"id":"termele-romane-germisara","name":"Termele romane Germisara","category":{"ro":"Sit arheologic roman","en":"Roman archaeological site"},"area":"Geoagiu","townId":"geoagiu","coords":[45.9358,23.1619],"hasReviews":true,"season":"tot-anul","images":["images/germisara-terme-romane.jpg"],"photoCredit":{"author":"Luthonium (Laurențiu Angheluță)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Germisara_thermal_baths.jpg"},"ro":{"tagline":"Băile romane din Geoagiu-Băi, cu bazine săpate în stâncă, unde se aduceau ofrande din aur divinităților apelor calde.","description":["Numele Germisara este de origine dacică, înseamnă „apă caldă” și apare pe Tabula Peutingeriana și la geograful Ptolemeu. Termele se află în centrul stațiunii Geoagiu-Băi, pe un promontoriu circular cu diametrul de 90–95 m, unde se văd și azi bazinele săpate în stâncă, canalele de scurgere și urmele unor construcții de cult. Băile au funcționat în două faze, ca Germisara și apoi ca Thermae Dodonae.","În 1935, la săparea unui bazin al ștrandului, au fost descoperite statuile lui Esculap și Hygeea. În 1986–1987 au ieșit la iveală altare și statui votive închinate Nimfelor și Dianei, precum și șapte plăcuțe votive din aur, lucrate în tehnica au repoussé — cinci cu inscripții, două cu imaginea Dianei și a trei nimfe. Plăcuțele se află astăzi în patrimoniul Muzeului Civilizației Dacice și Romane din Deva.","La circa 5 km sud de stațiune, lângă satul Cigmău, se află ruinele castrului roman Germisara, care supraveghea valea Mureșului."],"facts":[{"label":"Nume","value":"Germisara — „apă caldă” (de origine dacică)"},{"label":"Amplasare","value":"promontoriu circular de 90–95 m, în centrul stațiunii Geoagiu-Băi"},{"label":"Descoperiri","value":"statuile lui Esculap și Hygeea (1935); 7 plăcuțe votive din aur (1986–1987)"},{"label":"Unde vezi descoperirile","value":"Muzeul Civilizației Dacice și Romane, Deva"}]},"en":{"name":"Germisara Roman Baths","tagline":"The Roman baths of Geoagiu-Băi, with pools cut into the rock, where gold offerings were made to the deities of the warm springs.","description":["The name Germisara is of Dacian origin, means “hot water” and appears on the Tabula Peutingeriana and in the geographer Ptolemy. The baths lie in the centre of the Geoagiu-Băi resort, on a circular promontory 90–95 m across, where the rock-cut pools, drainage channels and traces of cult buildings are still visible. The baths were used in two phases, as Germisara and later as Thermae Dodonae.","In 1935, while a pool of the modern lido was being dug, statues of Aesculapius and Hygieia were found. In 1986–1987, altars and votive statues dedicated to the Nymphs and to Diana came to light, along with seven gold votive plaques made in the repoussé technique — five with inscriptions, two showing Diana and a group of three nymphs. The plaques now belong to the Museum of Dacian and Roman Civilisation in Deva.","About 5 km south of the resort, near the village of Cigmău, lie the ruins of the Roman fort of Germisara, which guarded the Mureș valley."],"facts":[{"label":"Name","value":"Germisara — “hot water” (of Dacian origin)"},{"label":"Setting","value":"circular promontory 90–95 m across, in the centre of Geoagiu-Băi"},{"label":"Finds","value":"statues of Aesculapius and Hygieia (1935); 7 gold votive plaques (1986–1987)"},{"label":"Where to see the finds","value":"Museum of Dacian and Roman Civilisation, Deva"}]}},{"id":"biserica-strei","name":"Biserica „Adormirea Maicii Domnului” din Strei","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Călan","townId":"calan","coords":[45.7165,22.9889],"hasReviews":true,"season":"tot-anul","images":["images/biserica-strei.jpg"],"photoCredit":{"author":"Valyemil81","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_%E2%80%9EAdormirea_Maicii_Domnului%E2%80%9D_-_Strei,_Humedoara.jpg"},"ro":{"tagline":"Biserică de piatră din jurul anului 1300, cu turn-clopotniță romanic și picturi murale medievale — una dintre cele mai vechi din Transilvania.","description":["Biserica ortodoxă din satul Strei, aparținător orașului Călan, este unul dintre cele mai vechi și mai reprezentative monumente de arhitectură medievală din Transilvania. Fostă capelă de curte a familiei cneziale locale, îmbină forme romanice — turnul masiv cu coif de piatră, ferestrele înguste — cu elemente ale goticului timpuriu, precum altarul boltit în cruce pe ogive și portalul vestic în arc frânt. Datarea e discutată: sfârșitul secolului al XIII-lea sau a doua jumătate a secolului al XIV-lea.","De mici dimensiuni și construită din piatră brută, biserica are un turn-clopotniță pe fațada de vest, o navă scurtă și un altar dreptunghiular. La baza turnului se văd două stele funerare romane refolosite, iar cimitirul din jur se suprapune parțial peste o „villa rustica” romană.","Interiorul păstrează un valoros ansamblu de picturi murale medievale — în altar „Iisus în slavă” și cortegiul apostolilor, în navă „Buna Vestire” și Sfântul Nicolae —, legat de numele meșterului Grozie, pomenit într-o inscripție din altar. Pictura a fost restaurată în 1970–1972 de pictorul Nicolae Sava."],"facts":[{"label":"Datare","value":"sfârșitul sec. XIII – sec. XIV"},{"label":"Localizare","value":"satul Strei, orașul Călan"},{"label":"Pictură murală","value":"medievală, restaurată în 1970–1972"},{"label":"Cod LMI","value":"HD-II-m-A-03452"}]},"en":{"name":"Church of the Dormition, Strei","tagline":"A stone church from around 1300, with a Romanesque bell tower and medieval murals — one of the oldest in Transylvania.","description":["The Orthodox church in the village of Strei, part of the town of Călan, is one of the oldest and most representative medieval buildings in Transylvania. Once the court chapel of the local knez family, it blends Romanesque forms — the massive tower with its stone spire, the narrow windows — with early Gothic features such as the rib-vaulted sanctuary and the pointed west portal. Its dating is debated: the late 13th century or the second half of the 14th century.","Small and built of rough stone, the church has a bell tower on its west front, a short nave and a rectangular sanctuary. Two reused Roman funerary stelae can be seen at the base of the tower, and the surrounding graveyard partly overlies a Roman villa rustica.","Inside survives a valuable set of medieval murals — Christ in Glory and the procession of apostles in the sanctuary, the Annunciation and Saint Nicholas in the nave — linked to the master painter Grozie, named in an inscription in the sanctuary. The murals were restored in 1970–1972 by the painter Nicolae Sava."],"facts":[{"label":"Dating","value":"late 13th – 14th century"},{"label":"Location","value":"Strei village, town of Călan"},{"label":"Murals","value":"medieval, restored in 1970–1972"},{"label":"Monument code (LMI)","value":"HD-II-m-A-03452"}]}},{"id":"biserica-santamaria-orlea","name":"Biserica reformată din Sântămăria-Orlea","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Țara Hațegului","townId":"santamaria-orlea","coords":[45.5906,22.9699],"hasReviews":true,"season":"tot-anul","images":["images/biserica-santamaria-orlea.jpg"],"photoCredit":{"author":"Zsolt deak","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_cnezilor_C%C3%A2ndea,_azi_Biserica_reformat%C4%83.JPG"},"ro":{"tagline":"Biserica cnezilor Cândea, ridicată în jurul anului 1280 — una dintre cele mai vechi biserici din spațiul românesc, cu picturi murale datate 1311.","description":["Biserica se află în Sântămăria-Orlea, la câțiva kilometri sud-est de Hațeg, pe un mic platou aproape de vechiul castel al familiei Kendeffy. A fost ridicată spre sfârșitul secolului al XIII-lea, în jurul anului 1280, este cunoscută ca biserica cnezilor Cândea și, inițial catolică, aparține astăzi cultului reformat (calvin). Satul apare în documente din 1315, iar în 1331 ca „villa Sancte Marie”.","Construită din piatră brută, cu muchii din piatră fățuită, are o navă dreptunghiulară tăvănită, un turn pătrat cu cinci niveluri pe fațada de vest, cu portal romanic bogat sculptat, și un altar boltit în cruce pe ogive. Formele ei ilustrează trecerea de la romanic la goticul timpuriu în Transilvania.","În interior se păstrează fragmente importante dintr-un ansamblu de pictură murală, scos de sub var începând din 1869. Etapa principală de pictură este datată printr-o inscripție latină în anul 1311."],"facts":[{"label":"Datare","value":"cca. 1280"},{"label":"Pictură murală","value":"etapa principală datată 1311 (inscripție latină)"},{"label":"Cult actual","value":"reformat (calvin); inițial catolică"},{"label":"Cod LMI","value":"HD-II-m-A-03445"}]},"en":{"name":"Reformed Church, Sântămăria-Orlea","tagline":"The church of the Cândea knezes, built around 1280 — one of the oldest churches in the Romanian lands, with murals dated 1311.","description":["The church stands in Sântămăria-Orlea, a few kilometres south-east of Hațeg, on a small plateau near the old Kendeffy family manor. Built towards the end of the 13th century, around 1280, it is known as the church of the Cândea knezes; originally Catholic, it now belongs to the Reformed (Calvinist) church. The village appears in records from 1315, and in 1331 as “villa Sancte Marie”.","Built of rough stone with dressed-stone corners, it has a flat-ceilinged rectangular nave, a square five-storey tower on its west front with a richly carved Romanesque portal, and a rib-vaulted sanctuary. Its forms illustrate the transition from Romanesque to early Gothic in Transylvania.","Inside, significant fragments survive of a mural scheme uncovered from beneath whitewash from 1869 onwards. The main painting phase is dated by a Latin inscription to the year 1311."],"facts":[{"label":"Dating","value":"around 1280"},{"label":"Murals","value":"main phase dated 1311 (Latin inscription)"},{"label":"Denomination today","value":"Reformed (Calvinist); originally Catholic"},{"label":"Monument code (LMI)","value":"HD-II-m-A-03445"}]}},{"id":"castelul-nopcsa-sacel","name":"Castelul Nopcsa din Săcel","category":{"ro":"Castel","en":"Castle"},"area":"Țara Hațegului","townId":"santamaria-orlea","coords":[45.5615,22.9277],"hasReviews":true,"season":"tot-anul","images":["images/castelul-nopcsa-sacel.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:CastelNopcsa_(9).JPG"},"ro":{"tagline":"Reședința familiei Nopcsa, legată de baronul-paleontolog Franz Nopcsa — restaurată și redeschisă publicului în 2025.","description":["Castelul din satul Săcel (comuna Sântămăria-Orlea) a fost ridicat în forma actuală în jurul anului 1872 de Elek Nopcsa, după ce domeniul trecuse de la familia Naláczy la familia Nopcsa. Clădirea, pe două niveluri, are un fronton zimțat pe fațada de vest, un turn de colț dreptunghiular cu creneluri și un turnuleț octogonal. Elek Nopcsa a practicat aici o agricultură modernă, fiind primul care a adus o mașină de treierat în județul Hunedoara.","Castelul este legat de numele fiului său, Franz Nopcsa (1877–1933) — aventurier, albanolog și unul dintre pionierii paleobiologiei. În 1895, sora lui, Ilona, a găsit oase de dinozaur pe domeniul familiei, iar studiul lor l-a dus pe Nopcsa la teoria nanismului insular, care explică dinozaurii pitici ai Țării Hațegului.","După decenii de degradare, castelul, proprietatea Consiliului Județean Hunedoara, a fost restaurat și redeschis pentru vizitare la 1 septembrie 2025, împreună cu Muzeul Civilizației Dacice și Romane din Deva, cu expoziția „Castelul Nopcsa – O călătorie prin timp în Țara Hațegului”. Fotografia este din 2012, dinaintea restaurării."],"facts":[{"label":"Construcție","value":"cca. 1872, de Elek Nopcsa"},{"label":"Personalitate","value":"Franz Nopcsa (1877–1933), paleontolog și albanolog"},{"label":"Redeschis","value":"1 septembrie 2025, după restaurare"},{"label":"Administrare","value":"CJ Hunedoara și Muzeul Civilizației Dacice și Romane Deva"},{"label":"Cod LMI","value":"HD-II-a-B-03439"}]},"en":{"name":"Nopcsa Castle, Săcel","tagline":"The Nopcsa family seat, linked to the paleontologist baron Franz Nopcsa — restored and reopened to the public in 2025.","description":["The manor in the village of Săcel (Sântămăria-Orlea commune) took its present form around 1872 under Elek Nopcsa, after the estate passed from the Naláczy family to the Nopcsas. The two-storey building has a stepped gable on its west front, a rectangular crenellated corner tower and a small octagonal turret. Elek Nopcsa farmed the estate in a modern way and was the first to bring a threshing machine to Hunedoara county.","The manor is tied to the name of his son, Franz Nopcsa (1877–1933) — adventurer, Albanologist and one of the pioneers of paleobiology. In 1895 his sister Ilona found dinosaur bones on the family estate, and studying them led Nopcsa to the theory of insular dwarfism, which explains the dwarf dinosaurs of Țara Hațegului.","After decades of decay, the manor, owned by Hunedoara County Council, was restored and reopened to visitors on 1 September 2025, together with the Museum of Dacian and Roman Civilisation in Deva, with the exhibition “Nopcsa Castle – A Journey Through Time in Țara Hațegului”. The photo dates from 2012, before the restoration."],"facts":[{"label":"Built","value":"around 1872, by Elek Nopcsa"},{"label":"Notable figure","value":"Franz Nopcsa (1877–1933), paleontologist and Albanologist"},{"label":"Reopened","value":"1 September 2025, after restoration"},{"label":"Managed by","value":"Hunedoara County Council and the Museum of Dacian and Roman Civilisation, Deva"},{"label":"Monument code (LMI)","value":"HD-II-a-B-03439"}]}},{"id":"cetatea-malaiesti","name":"Cetatea Mălăiești","category":{"ro":"Cetate medievală","en":"Medieval fortress"},"area":"Țara Hațegului","townId":"salasu-de-sus","coords":[45.4832,22.9474],"hasReviews":true,"season":"tot-anul","images":["images/cetatea-malaiesti.jpg"],"photoCredit":{"author":"Raimond Spekking","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Malaistii_fortress,_Romania-9103.jpg"},"ro":{"tagline":"Cetate nobiliară din secolul al XIV-lea, cu donjon și zid de incintă, restaurată cu fonduri europene, la poalele Retezatului.","description":["Cetatea se află în satul Mălăiești, comuna Sălașu de Sus, în sudul Țării Hațegului, spre Munții Retezat. Ansamblul — un donjon înconjurat de un zid de incintă din piatră — datează din secolul al XIV-lea și a fost ridicat de nobilii locali; ulterior, incinta a fost întărită cu patru turnuri.","Donjonul, înalt de circa 11 m, cu ziduri groase de 1,5 m, avea mai multe niveluri, cele inferioare folosite pentru provizii. Cetatea a fost părăsită în secolul al XVII-lea, iar o parte din piatra ei a fost refolosită în 1907–1909 la construcția bisericii ortodoxe din sat.","Monumentul a fost reabilitat cu fonduri preponderent europene, cu drum de acces, parcare, iluminat arhitectural și un mic amfiteatru pentru evenimente."],"facts":[{"label":"Datare","value":"secolul al XIV-lea"},{"label":"Componente","value":"donjon, zid de incintă, patru turnuri adăugate ulterior"},{"label":"Donjon","value":"~11 m înălțime, ziduri de 1,5 m"},{"label":"Localizare","value":"satul Mălăiești, comuna Sălașu de Sus"}]},"en":{"name":"Mălăiești Fortress","tagline":"A 14th-century noble fortress with a keep and curtain wall, restored with EU funds, at the foot of the Retezat.","description":["The fortress stands in the village of Mălăiești, Sălașu de Sus commune, in the south of Țara Hațegului towards the Retezat Mountains. The complex — a keep surrounded by a stone curtain wall — dates from the 14th century and was built by local nobles; the enclosure was later strengthened with four towers.","The keep, about 11 m high with 1.5 m thick walls, had several levels, the lower ones used for provisions. The fortress was abandoned in the 17th century, and some of its stone was reused in 1907–1909 to build the village's Orthodox church.","The monument was rehabilitated mostly with European funds, with an access road, parking, architectural lighting and a small amphitheatre for events."],"facts":[{"label":"Dating","value":"14th century"},{"label":"Components","value":"keep, curtain wall, four towers added later"},{"label":"Keep","value":"~11 m high, 1.5 m thick walls"},{"label":"Location","value":"Mălăiești village, Sălașu de Sus commune"}]}},{"id":"ulpia-traiana-sarmizegetusa","name":"Ulpia Traiana Sarmizegetusa","category":{"ro":"Sit arheologic roman","en":"Roman archaeological site"},"area":"Țara Hațegului","townId":"sarmizegetusa","coords":[45.5168,22.7866],"hasReviews":true,"season":"tot-anul","images":["images/ulpia-traiana-forum.jpg"],"photoCredit":{"author":"Razvan Socol","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Ulpia_Traiana_Sarmizegetusa_(5).JPG"},"ro":{"tagline":"Capitala Daciei romane, întemeiată după cucerirea din 106 d.Hr. — for, amfiteatru și temple în satul Sarmizegetusa.","description":["Colonia Ulpia Traiana Augusta Dacica Sarmizegetusa a fost întemeiată la porunca împăratului Traian de guvernatorul Decimus Terentius Scaurianus, la scurt timp după cucerirea Daciei (106 d.Hr.), pe locul unei tabere militare romane din Câmpia Hațegului. A fost capitala provinciei Dacia romană, iar sub împăratul Alexandru Sever (222–235) a primit titlul de metropolis.","Incinta fortificată, de circa 32 ha (600 × 540 m), avea forul în centru, la întretăierea celor două străzi principale; în afara zidurilor se aflau temple, locuințe, construcții publice și amfiteatrul, cu o capacitate de circa 5.000 de persoane. O mare parte din orașul antic nu a fost încă cercetată de arheologi.","Ruinele se vizitează în satul Sarmizegetusa, unde funcționează și Muzeul de Arheologie Sarmizegetusa, fondat în 1924, cu obiecte descoperite în săpături."],"facts":[{"label":"Întemeiere","value":"după 106 d.Hr., de guvernatorul Decimus Terentius Scaurianus"},{"label":"Rol","value":"capitala Daciei romane; metropolis sub Alexandru Sever"},{"label":"Incintă","value":"~32 ha (600 × 540 m)"},{"label":"Amfiteatru","value":"~5.000 de locuri"},{"label":"Muzeu","value":"Muzeul de Arheologie Sarmizegetusa (fondat în 1924)"}]},"en":{"tagline":"The capital of Roman Dacia, founded after the conquest of 106 AD — forum, amphitheatre and temples in the village of Sarmizegetusa.","description":["Colonia Ulpia Traiana Augusta Dacica Sarmizegetusa was founded on Emperor Trajan's orders by the governor Decimus Terentius Scaurianus, shortly after the conquest of Dacia (106 AD), on the site of a Roman military camp in the Hațeg plain. It was the capital of the province of Roman Dacia, and under Emperor Severus Alexander (222–235) it received the title of metropolis.","The walled area, about 32 ha (600 × 540 m), had the forum at its centre, where the two main streets crossed; outside the walls stood temples, houses, public buildings and the amphitheatre, which held about 5,000 people. Much of the ancient city has still not been excavated.","The ruins can be visited in the village of Sarmizegetusa, also home to the Sarmizegetusa Archaeological Museum, founded in 1924, with finds from the excavations."],"facts":[{"label":"Founded","value":"after 106 AD, by the governor Decimus Terentius Scaurianus"},{"label":"Role","value":"capital of Roman Dacia; metropolis under Severus Alexander"},{"label":"Walled area","value":"~32 ha (600 × 540 m)"},{"label":"Amphitheatre","value":"~5,000 seats"},{"label":"Museum","value":"Sarmizegetusa Archaeological Museum (founded 1924)"}]}},{"id":"cetatea-colt","name":"Cetatea Colț","category":{"ro":"Cetate medievală","en":"Medieval fortress"},"area":"Țara Hațegului","townId":"rau-de-mori","coords":[45.4781,22.8743],"hasReviews":true,"season":"tot-anul","images":["images/cetatea-colt-ruine.jpg"],"photoCredit":{"author":"TudorTulok","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Coltz_Citadel_in_Romania_View_from_Above.jpg"},"ro":{"tagline":"Ruinele cetății cnezilor Cândea, pe o stâncă la intrarea în defileul Râușorului — posibila inspirație pentru „Castelul din Carpați” al lui Jules Verne.","description":["Cetatea Colț a fost ridicată în secolul al XIV-lea de cneazul Cândea, ai cărui urmași au trecut la catolicism și și-au schimbat numele în Kendeffy. Se află pe teritoriul satului Suseni (comuna Râu de Mori), la circa 3 km de Râu de Mori, pe un colț de stâncă la intrarea în defileul Râușorului.","Construită în jurul unui turn pătrat, la care s-au adăugat un zid de incintă și alte turnuri, cetatea are un plan neregulat, adaptat stâncii. La mijlocul secolului al XVII-lea, călătorul otoman Evliya Çelebi o descria ca pe o cetate puternică, cu pante atât de abrupte încât era imposibil să te apropii de ea. Astăzi se mai păstrează doar ruinele zidurilor.","Datorită aspectului și toponimiei, se presupune că locul l-ar fi inspirat pe Jules Verne pentru romanul „Castelul din Carpați”. Până la ruine se ajunge pe un traseu marcat de circa o oră, din valea Nucșoara."],"facts":[{"label":"Datare","value":"secolul al XIV-lea"},{"label":"Ctitori","value":"cnezii Cândea (ulterior Kendeffy)"},{"label":"Localizare","value":"satul Suseni, comuna Râu de Mori"},{"label":"Acces","value":"traseu marcat cu triunghi albastru, cca. 1 oră"},{"label":"Stare","value":"ruină"}]},"en":{"name":"Colț Fortress","tagline":"The ruined fortress of the Cândea knezes, on a crag at the mouth of the Râușor gorge — a possible inspiration for Jules Verne's “The Carpathian Castle”.","description":["Colț Fortress was built in the 14th century by the knez Cândea, whose descendants converted to Catholicism and changed their name to Kendeffy. It stands within the village of Suseni (Râu de Mori commune), about 3 km from Râu de Mori, on a rocky spur at the entrance to the Râușor gorge.","Built around a square tower, later joined by a curtain wall and further towers, the fortress has an irregular plan shaped by the rock. In the mid-17th century the Ottoman traveller Evliya Çelebi described it as a mighty stronghold whose slopes were so steep it was impossible to approach. Today only the ruined walls remain.","Because of its look and the local place names, the site is believed to have inspired Jules Verne's novel “The Carpathian Castle”. The ruins are reached on a marked trail of about an hour from the Nucșoara valley."],"facts":[{"label":"Dating","value":"14th century"},{"label":"Founders","value":"The Cândea knezes (later Kendeffy)"},{"label":"Location","value":"Suseni village, Râu de Mori commune"},{"label":"Access","value":"trail marked with a blue triangle, about 1 hour"},{"label":"Condition","value":"ruin"}]}},{"id":"rotonda-geoagiu","name":"Rotonda din Geoagiu","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Geoagiu","townId":"geoagiu","coords":[45.920062,23.20316],"hasReviews":true,"season":"tot-anul","images":["images/rotonda-geoagiu.jpg"],"photoCredit":{"author":"Levente Nuber","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Capela_romanic%C4%83_din_Geoagiu_1.jpg"},"ro":{"tagline":"Capela romanică de plan circular, probabil cea mai veche biserică medievală de pe teritoriul României.","description":["Rotonda — capela romanică din Geoagiu — este o biserică de plan circular, cu o absidă spre est, zidită aproape în întregime din cărămidă romană refolosită, luată de la o construcție mai veche aflată pe același loc. Nava are 5,5 m diametru în interior, iar întreaga clădire măsoară 9,5 m în lungime. Se crede că a fost ridicată spre sfârșitul secolului al XI-lea de familia nobiliară Ákos, care stăpânea atunci Geoagiul.","Săpăturile arheologice din 1993–2004, conduse de Gheorghe Petrov, au scos la lumină peste 200 de morminte în jurul și în interiorul bisericii; cele mai vechi datează din vremea regilor Ladislau I (1077–1095) și Coloman (1095–1116), deci rotonda exista deja la sfârșitul secolului al XI-lea. O legendă locală o leagă de cavalerii templieri. Azi nu se mai slujește în ea și se vizitează ca muzeu; la câțiva metri se află biserica reformată gotică, cu reliefuri romane în ziduri."],"facts":[{"label":"Datare","value":"probabil sfârșitul sec. XI"},{"label":"Plan","value":"circular, cu absidă; cărămidă romană refolosită"},{"label":"Cercetări","value":"1993–2004, peste 200 de morminte descoperite"},{"label":"Localizare","value":"orașul Geoagiu, lângă biserica reformată"},{"label":"Cod LMI","value":"HD-II-m-A-03316"}]},"en":{"name":"Geoagiu Rotunda","tagline":"A circular Romanesque chapel, probably the oldest medieval church on Romanian territory.","description":["The Rotunda — Geoagiu's Romanesque chapel — is a round church with an apse to the east, built almost entirely of reused Roman brick taken from an older building on the same spot. The nave is 5.5 m across inside and the whole building is 9.5 m long. It is thought to have been raised in the late 11th century by the Ákos noble family, who then held Geoagiu.","Excavations in 1993–2004, led by Gheorghe Petrov, uncovered more than 200 graves around and inside the church; the oldest date from the reigns of kings Ladislaus I (1077–1095) and Coloman (1095–1116), so the rotunda already stood by the end of the 11th century. A local legend links it to the Knights Templar. Services are no longer held there and it is visited as a museum; a few metres away stands the Gothic Reformed church, with Roman reliefs in its walls."],"facts":[{"label":"Date","value":"probably late 11th century"},{"label":"Plan","value":"circular, with an apse; reused Roman brick"},{"label":"Research","value":"1993–2004, more than 200 graves found"},{"label":"Location","value":"Geoagiu town, next to the Reformed church"},{"label":"LMI code","value":"HD-II-m-A-03316"}]}},{"id":"biserica-bozes","name":"Biserica „Sfinții Arhangheli” din Bozeș","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Geoagiu","townId":"geoagiu","coords":[45.977425,23.171824],"hasReviews":true,"season":"tot-anul","images":["images/biserica-bozes.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Bozes_4.jpg"},"ro":{"tagline":"Fostă capelă de curte din piatră, de la începutul secolului al XVI-lea, într-un sat de deal de lângă Geoagiu-Băi.","description":["În satul Bozeș, aparținător orașului Geoagiu, se păstrează o biserică de piatră cu plan dreptunghiular și absidă pentagonală decroșată, ridicată — potrivit tradiției locale — la începutul secolului al XVI-lea de unul dintre domnitorii sau boierii români de la sud de Carpați care stăpâneau atunci domeniul Geoagiului de Jos, din care făcea parte și Bozeșul.","Gândită la început ca o capelă de curte, biserica a fost pictată la sfârșitul secolului al XVIII-lea de un zugrav popular rămas anonim. Satul e aproape de stațiunea Geoagiu-Băi, așa că biserica se poate vizita ușor pornind de acolo."],"facts":[{"label":"Datare","value":"începutul sec. XVI (după tradiție)"},{"label":"Pictură","value":"sfârșitul sec. XVIII, zugrav anonim"},{"label":"Localizare","value":"satul Bozeș, orașul Geoagiu"},{"label":"Cod LMI","value":"HD-II-m-A-03262"}]},"en":{"name":"Church of the Holy Archangels, Bozeș","tagline":"A former stone court chapel from the early 16th century, in a hill village near Geoagiu-Băi.","description":["The village of Bozeș, part of the town of Geoagiu, keeps a stone church with a rectangular nave and a narrower five-sided apse, built — according to local tradition — in the early 16th century by one of the Romanian princes or boyars from south of the Carpathians who then held the Lower Geoagiu estate, Bozeș included.","First intended as a court chapel, the church was painted in the late 18th century by an anonymous folk painter. The village is close to the Geoagiu-Băi spa, so the church makes an easy outing from the resort."],"facts":[{"label":"Date","value":"early 16th century (by tradition)"},{"label":"Murals","value":"late 18th century, anonymous painter"},{"label":"Location","value":"Bozeș village, Geoagiu town"},{"label":"LMI code","value":"HD-II-m-A-03262"}]}},{"id":"biserica-streisangeorgiu","name":"Biserica Sf. Gheorghe din Streisângeorgiu","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Călan","townId":"calan","coords":[45.7289,23.0226],"hasReviews":true,"season":"tot-anul","images":["images/biserica-streisangeorgiu.jpg"],"photoCredit":{"author":"Oguszt","license":"CC BY-SA 3.0 / GFDL","source":"https://commons.wikimedia.org/wiki/File:Sztrigyszentgy%C3%B6rgyi_ortodox_templom.jpg"},"ro":{"tagline":"Biserică romanică din 1313–1314, cu pictură din trei epoci — una dintre cele mai vechi biserici din România încă în folosință.","description":["La marginea orașului Călan, în Streisângeorgiu, se află una dintre cele mai vechi construcții medievale din Transilvania aflate încă în funcțiune. O inscripție slavo-română descoperită în altar arată că biserica de zid a fost făcută în 1313–1314, „cu ajutorul sfântului Gheorghe”, pentru iertarea păcatelor cneazului Balea și ale popii Naneș, iar pictura a fost lucrată de Teofil zugravul.","Săpăturile au arătat că pe același loc a existat înainte o biserică de lemn, cu același plan, iar mormintele din jur datează din secolele XII–XIII. Pictura interioară se păstrează din trei etape — 1313–1314, 1409 și 1743 —, iar în zidurile bisericii se văd lespezi romane aduse de la o villa rustica din apropiere."],"facts":[{"label":"Datare","value":"1313–1314 (după inscripția din altar)"},{"label":"Ctitori","value":"cneazul Balea și popa Naneș; zugrav Teofil"},{"label":"Pictură","value":"1313–1314, 1409 și 1743"},{"label":"Localizare","value":"Streisângeorgiu, orașul Călan"},{"label":"Cod LMI","value":"HD-II-m-A-03454"}]},"en":{"name":"St George's Church, Streisângeorgiu","tagline":"A Romanesque church from 1313–1314 with murals from three periods — one of Romania's oldest churches still in use.","description":["On the edge of Călan, in Streisângeorgiu, stands one of the oldest medieval buildings in Transylvania still in use. A Slavonic-Romanian inscription found in the altar says the stone church was made in 1313–1314, “with the help of Saint George”, for the forgiveness of the sins of the knez Balea and the priest Naneș, and that it was painted by Teofil the painter.","Excavations showed that a wooden church with the same plan stood here earlier, and the graves around it date from the 12th–13th centuries. The murals survive from three stages — 1313–1314, 1409 and 1743 — and Roman slabs from a nearby villa rustica can be seen in the walls."],"facts":[{"label":"Date","value":"1313–1314 (from the altar inscription)"},{"label":"Founders","value":"knez Balea and priest Naneș; painter Teofil"},{"label":"Murals","value":"1313–1314, 1409 and 1743"},{"label":"Location","value":"Streisângeorgiu, Călan town"},{"label":"LMI code","value":"HD-II-m-A-03454"}]}},{"id":"curtea-candestilor-rau-de-mori","name":"Curtea nobiliară a Cândeștilor","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Râu de Mori","townId":"rau-de-mori","coords":[45.495639,22.853512],"hasReviews":true,"season":"tot-anul","images":["images/curtea-candestilor-rau-de-mori.jpg"],"photoCredit":{"author":"Andrei kokelburg","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Rau_de_Mori_Curtea_(1).jpg"},"ro":{"tagline":"Ruinele reședinței cnezilor Cândea — cea mai puternică familie românească din Țara Hațegului — în centrul satului Râu de Mori.","description":["În centrul satului Râu de Mori se văd ruinele curții nobiliare a familiei Cândea: clădirea de locuit, capela de curte și zidul de incintă. Ansamblul a fost ridicat în secolul al XIV-lea peste ruinele unor clădiri romane; cel mai vechi membru cunoscut al familiei, Nicolae Cândea, a trăit pe la 1300.","Cândeștii au ajuns să stăpânească, până la sfârșitul secolului al XV-lea, 30 de sate întregi sau părți de sate din Țara Hațegului, iar Iancu de Hunedoara le-a întărit în 1447 târgul Sântămăria-Orlea. Familia s-a împărțit apoi în două ramuri, Kendeffy și Kenderessy. În fața ruinelor, în cimitir, se află biserica „Duminica Tuturor Sfinților”, fosta capelă a Cândeștilor."],"facts":[{"label":"Datare","value":"sec. XIV–XVI, transformări în sec. XVII–XIX"},{"label":"Ansamblu","value":"curia, capela de curte, zidul de incintă"},{"label":"Familie","value":"cnezii Cândea (mai târziu Kendeffy și Kenderessy)"},{"label":"Stare","value":"ruină, vizibilă din sat"},{"label":"Cod LMI","value":"HD-II-a-A-03428"}]},"en":{"name":"Cândea Noble Court","tagline":"The ruins of the seat of the Cândea knezes — the most powerful Romanian family in the Hațeg Country — in the middle of Râu de Mori.","description":["In the centre of Râu de Mori stand the ruins of the Cândea family's noble court: the residence, the court chapel and the enclosure wall. The complex was built in the 14th century over the ruins of Roman buildings; the earliest known member of the family, Nicolae Cândea, lived around 1300.","By the end of the 15th century the Cândeas held 30 whole or partial villages in the Hațeg Country, and in 1447 John Hunyadi confirmed them in possession of the market town of Sântămăria-Orlea. The family later split into two branches, the Kendeffy and the Kenderessy. In the cemetery in front of the ruins stands the All Saints' Sunday Church, the Cândeas' former chapel."],"facts":[{"label":"Date","value":"14th–16th centuries, altered in the 17th–19th"},{"label":"Complex","value":"residence, court chapel, enclosure wall"},{"label":"Family","value":"The Cândea knezes (later Kendeffy and Kenderessy)"},{"label":"Condition","value":"ruin, visible from the village"},{"label":"LMI code","value":"HD-II-a-A-03428"}]}},{"id":"biserica-ostrov","name":"Biserica „Pogorârea Sfântului Duh” din Ostrov","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Râu de Mori","townId":"rau-de-mori","coords":[45.527888,22.846511],"hasReviews":true,"season":"tot-anul","images":["images/biserica-ostrov.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:OstrovHD_(66).JPG"},"ro":{"tagline":"Una dintre cele mai vechi biserici românești de zid din Transilvania, ctitorie a cnezilor locali din secolul al XIV-lea.","description":["Satul Ostrov, din comuna Râu de Mori, stă pe vechiul drum roman dintre Sarmizegetusa și ieșirea Streiului din depresiune și își are numele de la poziția sa, înconjurată de Râul Mare și Apa Borii. Biserica „Pogorârea Sfântului Duh”, ctitorită de cnezii locali, e anterioară mijlocului secolului al XIV-lea; în 1360, Petru de Ostrov era primul protopop cunoscut al districtului.","Din construcția inițială se mai păstrează doar pereții de sud și de vest ai navei; imaginea de azi e rezultatul transformărilor din a doua jumătate a secolului al XVIII-lea și de la începutul secolului al XIX-lea. Familia nobiliară a satului a trecut de la catolicism la calvinism, apoi biserica a fost greco-catolică, iar după 1948 ortodoxă. Cercetările arheologice din 1996 au stabilit etapele construcției."],"facts":[{"label":"Datare","value":"sec. XIV (înainte de 1360)"},{"label":"Păstrat din faza inițială","value":"pereții de sud și de vest ai navei"},{"label":"Localizare","value":"satul Ostrov, comuna Râu de Mori"},{"label":"Cod LMI","value":"HD-II-a-A-03400"}]},"en":{"name":"Church of the Descent of the Holy Spirit, Ostrov","tagline":"One of the oldest Romanian stone churches in Transylvania, founded by local knezes in the 14th century.","description":["Ostrov, in Râu de Mori commune, lies on the old Roman road between Sarmizegetusa and the point where the Strei leaves the basin, and takes its name (“islet”) from its setting, surrounded by the Râul Mare and the Apa Borii. The Church of the Descent of the Holy Spirit, founded by local knezes, predates the mid-14th century; in 1360 Peter of Ostrov was the district's first known archpriest.","Only the south and west walls of the nave survive from the first building; today's appearance results from works in the second half of the 18th century and the early 19th. The village's noble family moved from Catholicism to Calvinism, the church later became Greek Catholic and, after 1948, Orthodox. Excavations in 1996 established its building phases."],"facts":[{"label":"Date","value":"14th century (before 1360)"},{"label":"Surviving from the first phase","value":"south and west walls of the nave"},{"label":"Location","value":"Ostrov village, Râu de Mori commune"},{"label":"LMI code","value":"HD-II-a-A-03400"}]}},{"id":"biserica-pesteana","name":"Biserica medievală din Peșteana","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Densuș","townId":"densus","coords":[45.54972,22.82278],"hasReviews":true,"season":"tot-anul","images":["images/biserica-pesteana.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_din_Pesteana_(11).JPG"},"ro":{"tagline":"Biserică de piatră din secolul al XIII-lea, zidită cu blocuri romane refolosite, la câțiva kilometri de Densuș.","description":["În mijlocul satului Peșteana, atestat în 1360 prin preotul „Balk de Possana”, se află biserica „Pogorârea Sfântului Duh”, martoră a vechilor familii cneziale din Țara Hațegului. Este alcătuită dintr-o navă dreptunghiulară, un altar de influență romanică și un turn-clopotniță pe latura de vest, iar la construcție s-au folosit blocuri masive de piatră luate din clădiri romane ruinate.","Săpăturile au pus în evidență două faze de construcție: o primă capelă de curte, cu altar semicircular, și o biserică mai mare, din secolul al XIII-lea, căreia îi aparține portalul de sub clopotniță. Restaurarea din 1925–1926, a arhitectului Rudolf Wagner, i-a schimbat mult înfățișarea — decorul de tencuială cu firide circulare și etajul turnului sunt de atunci."],"facts":[{"label":"Datare","value":"sec. XIII (faza a doua); prima fază mai veche"},{"label":"Material","value":"piatră, cu blocuri romane refolosite"},{"label":"Restaurare","value":"1925–1926 (arh. Rudolf Wagner)"},{"label":"Localizare","value":"satul Peșteana, comuna Densuș"},{"label":"Cod LMI","value":"HD-II-m-A-03405"}]},"en":{"name":"Medieval Church, Peșteana","tagline":"A 13th-century stone church built with reused Roman blocks, a few kilometres from Densuș.","description":["In the middle of Peșteana, recorded in 1360 through its priest “Balk de Possana”, stands the Church of the Descent of the Holy Spirit, a witness to the old knez families of the Hațeg Country. It has a rectangular nave, a Romanesque-style altar and a bell tower on the west side, and was built with massive stone blocks taken from ruined Roman buildings.","Excavations revealed two building phases: a first court chapel with a semicircular altar, and a larger 13th-century church, to which the portal under the bell tower belongs. The 1925–1926 restoration by architect Rudolf Wagner changed its look considerably — the plaster decoration with round niches and the upper storey of the tower date from then."],"facts":[{"label":"Date","value":"13th century (second phase); first phase older"},{"label":"Material","value":"stone, with reused Roman blocks"},{"label":"Restoration","value":"1925–1926 (architect Rudolf Wagner)"},{"label":"Location","value":"Peșteana village, Densuș commune"},{"label":"LMI code","value":"HD-II-m-A-03405"}]}},{"id":"bastionul-rosu-ilia","name":"Bastionul Roșu — Casa natală Gabriel Bethlen","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Ilia","townId":"ilia","coords":[45.934214,22.651404],"hasReviews":true,"season":"tot-anul","images":["images/bastionul-rosu-ilia.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:BastionulRosuIlia_(9).JPG"},"ro":{"tagline":"Bastionul din 1582 al cetății de graniță de la Ilia, cunoscut drept locul de naștere al principelui Gabriel Bethlen.","description":["După căderea cetății Lipova în mâinile turcilor (1552), Ilia a devenit cetate de graniță și a fost înconjurată cu un inel de bastioane. Farkas Bethlen, căruia principele Ștefan Báthory îi dăduse domeniul, a ridicat în 1582 Bastionul Roșu — mai mic și mai puțin expus, gândit de la început pentru locuit, cu ancadramente de piatră sculptată și pictură decorativă pe exterior.","Fiul lui Farkas, Gabriel Bethlen, principe al Transilvaniei între 1613 și 1629, s-a născut aici în 1580, de fapt în turnul de locuință al cetății, demolat ulterior. În 1670 celelalte bastioane și zidurile au fost dărâmate, iar Bastionul Roșu, refăcut în stil romantic după 1850, a ajuns să fie identificat cu locul nașterii principelui; placa comemorativă de azi a fost pusă după refacerea din 1909."],"facts":[{"label":"Construit","value":"1582, de Farkas Bethlen"},{"label":"Personalitate","value":"Gabriel Bethlen (1580–1629), principe al Transilvaniei 1613–1629"},{"label":"Refaceri","value":"după 1850 (stil romantic) și 1909"},{"label":"Localizare","value":"satul Ilia, comuna Ilia"},{"label":"Cod LMI","value":"HD-II-m-A-03353"}]},"en":{"name":"Red Bastion — Gabriel Bethlen's Birthplace","tagline":"The 1582 bastion of Ilia's border fortress, known as the birthplace of Prince Gabriel Bethlen.","description":["After the Ottomans took the fortress of Lipova in 1552, Ilia became a border stronghold and was ringed with bastions. Farkas Bethlen, granted the estate by Prince Stephen Báthory, built the Red Bastion in 1582 — smaller and less exposed, designed from the start as a residence, with carved stone frames and painted decoration on the outside.","Farkas's son Gabriel Bethlen, Prince of Transylvania from 1613 to 1629, was born here in 1580 — in fact in the fortress's residential tower, later demolished. In 1670 the other bastions and the walls were pulled down, and the Red Bastion, rebuilt in Romantic style after 1850, came to be identified with the prince's birthplace; today's memorial plaque was put up after the 1909 restoration."],"facts":[{"label":"Built","value":"1582, by Farkas Bethlen"},{"label":"Notable person","value":"Gabriel Bethlen (1580–1629), Prince of Transylvania 1613–1629"},{"label":"Rebuilt","value":"after 1850 (Romantic style) and 1909"},{"label":"Location","value":"Ilia village, Ilia commune"},{"label":"LMI code","value":"HD-II-m-A-03353"}]}},{"id":"biserica-de-lemn-bretea-mureseana","name":"Biserica de lemn din Bretea Mureșană","category":{"ro":"Biserică de lemn","en":"Wooden church"},"area":"Ilia","townId":"ilia","coords":[45.93611,22.71306],"hasReviews":true,"season":"tot-anul","images":["images/biserica-de-lemn-bretea-mureseana.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_de_lemn_din_Bretea_Mure%C8%99an%C4%83.jpg"},"ro":{"tagline":"Biserică de lemn sfințită la 3 martie 1653, cu două pisanii în limba română scrise cu litere chirilice.","description":["Biserica de lemn din cimitirul satului Bretea Mureșană, cu hramul Sfântul Dumitru, a fost sfințită, după pisanie, la 3 martie 1653, în vremea principelui Gheorghe Rákóczi. Cele două inscripții, în limba română cu litere chirilice, pomenesc ctitorii — între ei „Eva muma Giurgeștilor” — și preotul satului, iar clopotul original, aflat acum în clopotnița bisericii noi, e din 1665.","Lăcașul, de plan dreptunghiular cu colțurile teșite, se înscrie în tipul clasic vest-ardelean. A fost însă mult schimbat: pronaosul a fost mărit, intrarea mutată, iar „restaurarea” din 1965–1969 a scurtat turnul-clopotniță cu 3 m și a așezat biserica pe o fundație de beton."],"facts":[{"label":"Sfințită","value":"3 martie 1653"},{"label":"Hram","value":"Sfântul Dumitru"},{"label":"Particularitate","value":"două pisanii în română, cu litere chirilice"},{"label":"Localizare","value":"satul Bretea Mureșană, comuna Ilia"},{"label":"Cod LMI","value":"HD-II-m-A-03272"}]},"en":{"name":"Wooden Church, Bretea Mureșană","tagline":"A wooden church consecrated on 3 March 1653, with two inscriptions in Romanian written in Cyrillic letters.","description":["The wooden church in the cemetery of Bretea Mureșană, dedicated to Saint Demetrius, was consecrated on 3 March 1653, according to its inscription, in the time of Prince George Rákóczi. The two inscriptions, in Romanian written in Cyrillic, name the founders — among them “Eva, mother of the Giurgești” — and the village priest, and the original bell, now in the bell tower of the new church, dates from 1665.","With its rectangular plan and bevelled corners, the church belongs to the classic western Transylvanian type. It has been much altered, though: the narthex was enlarged, the entrance moved, and the 1965–1969 “restoration” cut 3 m off the bell tower and set the church on a concrete foundation."],"facts":[{"label":"Consecrated","value":"3 March 1653"},{"label":"Dedication","value":"Saint Demetrius"},{"label":"Notable","value":"two inscriptions in Romanian, in Cyrillic letters"},{"label":"Location","value":"Bretea Mureșană village, Ilia commune"},{"label":"LMI code","value":"HD-II-m-A-03272"}]}},{"id":"biserica-ponor","name":"Biserica „Pogorârea Sfântului Duh” din Ponor","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Pui","townId":"pui","coords":[45.51,23.12778],"hasReviews":true,"season":"tot-anul","images":["images/biserica-ponor.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_din_Ponor_(9).JPG"},"ro":{"tagline":"Biserică de piatră din 1769, pictată în 1846, în satul de la poalele Șureanului unde au trăit cnezii Ponori.","description":["Ponor, sat al comunei Pui la poalele sud-vestice ale Munților Șureanu, a fost reședința familiei cneziale românești Ponori. Biserica de piatră „Pogorârea Sfântului Duh” a fost ridicată în 1769, pe un teren de la marginea satului cedat obștii de familia nobiliară reformată Török, care voia să-și construiască propria biserică pe locul celei vechi.","Edificiul are plan dreptunghiular, absidă semicirculară și un turn-clopotniță suplu, cu foișor deschis de lemn. Interiorul a fost pictat în 1846, iar restaurarea din 1883 l-a păstrat în stare bună până azi."],"facts":[{"label":"Construită","value":"1769"},{"label":"Pictură","value":"1846"},{"label":"Restaurări","value":"1883, 1991"},{"label":"Localizare","value":"satul Ponor, comuna Pui"},{"label":"Cod LMI","value":"HD-II-m-B-03416"}]},"en":{"name":"Church of the Descent of the Holy Spirit, Ponor","tagline":"A stone church from 1769, painted in 1846, in the village below the Șureanu where the Ponori knezes lived.","description":["Ponor, a village of Pui commune at the south-western foot of the Șureanu Mountains, was the seat of the Romanian knez family Ponori. The stone Church of the Descent of the Holy Spirit was built in 1769 on land at the edge of the village given to the community by the Reformed noble family Török, who wanted to build their own church on the site of the old one.","It has a rectangular plan, a semicircular apse and a slender bell tower with an open wooden gallery. The interior was painted in 1846, and the 1883 restoration has kept it in good condition to this day."],"facts":[{"label":"Built","value":"1769"},{"label":"Murals","value":"1846"},{"label":"Restorations","value":"1883, 1991"},{"label":"Location","value":"Ponor village, Pui commune"},{"label":"LMI code","value":"HD-II-m-B-03416"}]}},{"id":"biserica-de-lemn-soimus","name":"Biserica de lemn din Șoimuș","category":{"ro":"Biserică de lemn","en":"Wooden church"},"area":"Șoimuș","townId":"soimus","coords":[45.91694,22.88972],"hasReviews":true,"season":"tot-anul","images":["images/biserica-de-lemn-soimus.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Soimus_49.jpg"},"ro":{"tagline":"Biserică din bârne de stejar ridicată în 1705, cu iconostas de icoane pe sticlă din 1830.","description":["Biserica de lemn „Sfântul Nicolae” din Șoimuș a fost ridicată în 1705, an dăltuit în pragul de sus al ușii spre naos. E construită din bârne de stejar, cu plan dreptunghiular și absida poligonală în prelungire; în secolul al XIX-lea a fost lungită spre vest cu un pronaos, peste care s-a ridicat o clopotniță scundă cu foișor și fleșă piramidală.","Merită privit ancadramentul intrării de pe latura de sud, ornamentat cu cruci piezișe, motivul „dinte de lup” și rozete. Iconostasul e alcătuit din icoane pictate pe sticlă în 1830."],"facts":[{"label":"Construită","value":"1705"},{"label":"Hram","value":"Sfântul Nicolae"},{"label":"Iconostas","value":"icoane pe sticlă, 1830"},{"label":"Localizare","value":"satul Șoimuș, comuna Șoimuș"},{"label":"Cod LMI","value":"HD-II-m-A-03461"}]},"en":{"name":"Wooden Church, Șoimuș","tagline":"An oak-log church built in 1705, with an iconostasis of icons painted on glass in 1830.","description":["The wooden St Nicholas Church in Șoimuș was built in 1705, the year carved into the lintel of the door to the nave. It is made of oak logs, with a rectangular plan and a polygonal apse in line with the nave; in the 19th century it was extended west with a narthex, topped by a low bell tower with a gallery and pyramidal spire.","Look out for the carved frame of the south entrance, decorated with diagonal crosses, “wolf's tooth” patterns and rosettes. The iconostasis is made of icons painted on glass in 1830."],"facts":[{"label":"Built","value":"1705"},{"label":"Dedication","value":"Saint Nicholas"},{"label":"Iconostasis","value":"icons on glass, 1830"},{"label":"Location","value":"Șoimuș village, Șoimuș commune"},{"label":"LMI code","value":"HD-II-m-A-03461"}]}},{"id":"biserica-de-lemn-radulesti","name":"Biserica de lemn din Rădulești","category":{"ro":"Biserică de lemn","en":"Wooden church"},"area":"Dobra","townId":"dobra","coords":[45.88111,22.62667],"hasReviews":true,"season":"tot-anul","images":["images/biserica-de-lemn-radulesti.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Radulesti_5.jpg"},"ro":{"tagline":"Biserică de lemn din secolul al XVIII-lea, mărită în 1790 și pictată în întregime pe dinăuntru.","description":["Biserica de lemn „Cuvioasa Paraschiva” din Rădulești, comuna Dobra, a fost construită în secolul al XVIII-lea; tradiția și sursele dau ani diferiți pentru ridicarea ei. La început avea un altar poligonal, o navă modestă și o clopotniță scundă spre apus.","În 1790, sub preotul Gheorghie, a fost mărită: s-a adăugat o travee, turnul a fost înălțat și i s-a dat un foișor, iar pereții au fost tencuiți pe dinăuntru și pictați în întregime, la fel ca iconostasul. În 1888 i s-a adăugat o prispă îngustă pe un soclu de piatră. Biserica apare pe harta iosefină a Transilvaniei (1769–1773)."],"facts":[{"label":"Construită","value":"sec. XVIII"},{"label":"Renovare mare","value":"1790 (mărire, pictură interioară)"},{"label":"Hram","value":"Cuvioasa Paraschiva"},{"label":"Localizare","value":"satul Rădulești, comuna Dobra"},{"label":"Cod LMI","value":"HD-II-m-A-03426"}]},"en":{"name":"Wooden Church, Rădulești","tagline":"An 18th-century wooden church, enlarged in 1790 and painted throughout inside.","description":["The wooden church of St Paraskeva in Rădulești, Dobra commune, was built in the 18th century; tradition and sources give different years for its construction. It originally had a polygonal altar, a modest nave and a low bell tower to the west.","In 1790, under the priest Gheorghie, it was enlarged: a bay was added, the tower was raised and given a gallery, and the walls were plastered inside and painted throughout, as was the iconostasis. A narrow porch on a stone base was added in 1888. The church appears on the Josephine map of Transylvania (1769–1773)."],"facts":[{"label":"Built","value":"18th century"},{"label":"Major renovation","value":"1790 (enlarged, painted inside)"},{"label":"Dedication","value":"St Paraskeva"},{"label":"Location","value":"Rădulești village, Dobra commune"},{"label":"LMI code","value":"HD-II-m-A-03426"}]}},{"id":"biserica-lapusnic","name":"Biserica „Cuvioasa Paraschiva” din Lăpușnic","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Dobra","townId":"dobra","coords":[45.91167,22.61861],"hasReviews":true,"season":"tot-anul","images":["images/biserica-lapusnic.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:LapusnicHD_(43).JPG"},"ro":{"tagline":"Biserică de piatră din secolul al XVII-lea, cu o boltă pictată în 1726 pe căptușeală de scânduri.","description":["În satul Lăpușnic, la poalele nordice ale Munților Poiana Ruscă, se păstrează o biserică de zid clasată monument istoric încă din 1948. Partea cea mai veche a naosului, de la mijlocul secolului al XVII-lea, a fost la origine o clădire civilă, donată de văduva Maria de Lazar.","Altarul și lungirea navei datează din prima jumătate a secolului al XVIII-lea — pe boltă e scris „1726 martie 26” —, iar pronaosul și clopotnița au fost adăugate în 1832–1843. Bolta navei și a altarului a fost pictată în 1726 pe o căptușeală de scânduri, de un zugrav necunoscut, și repictată în 1817; pictura e azi într-o stare avansată de degradare."],"facts":[{"label":"Datare","value":"mijlocul sec. XVII; altar 1726; pronaos și turn 1832–1843"},{"label":"Pictură","value":"1726 (pe scânduri), repictată în 1817"},{"label":"Plan","value":"dreptunghiular, 21 × 7 m, absidă semicirculară"},{"label":"Localizare","value":"satul Lăpușnic, comuna Dobra"},{"label":"Cod LMI","value":"HD-II-m-A-03357"}]},"en":{"name":"St Paraskeva Church, Lăpușnic","tagline":"A 17th-century stone church with a vault painted in 1726 on a lining of wooden boards.","description":["The village of Lăpușnic, at the northern foot of the Poiana Ruscă Mountains, keeps a stone church listed as a historic monument since 1948. The oldest part of the nave, from the mid-17th century, was originally a civil building donated by the widow Maria de Lazar.","The altar and the lengthened nave date from the first half of the 18th century — “1726 March 26” is written on the vault — and the narthex and bell tower were added in 1832–1843. The vault over the nave and altar was painted in 1726 on a board lining by an unknown painter and repainted in 1817; the murals are now badly deteriorated."],"facts":[{"label":"Date","value":"mid-17th century; altar 1726; narthex and tower 1832–1843"},{"label":"Murals","value":"1726 (on boards), repainted 1817"},{"label":"Plan","value":"rectangular, 21 × 7 m, semicircular apse"},{"label":"Location","value":"Lăpușnic village, Dobra commune"},{"label":"LMI code","value":"HD-II-m-A-03357"}]}},{"id":"biserica-de-lemn-ciungani","name":"Biserica de lemn din Ciungani","category":{"ro":"Biserică de lemn","en":"Wooden church"},"area":"Vața de Jos","townId":"vata-de-jos","coords":[46.18556,22.50056],"hasReviews":true,"season":"tot-anul","images":["images/biserica-de-lemn-ciungani.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Ciungani_5.jpg"},"ro":{"tagline":"Biserică de lemn de pe la 1600, cu cel mai înalt turn dintre bisericile de lemn hunedorene — 14 m.","description":["Pe dealul „Zapoza” din satul Ciungani, în Țara Zarandului, se află biserica de lemn „Buna Vestire”, ridicată, după tradiție, în jurul anului 1600 — dată confirmată de planul ei arhaic. În 1755 era descrisă ca „de lemn, veche, nesfințită”. Acoperișul cu pante repezi și fleșa turnului-clopotniță, înaltă de 14 m — cea mai înaltă dintre bisericile de lemn din județ —, sunt învelite în șiță.","Înăuntru se văd două etape de pictură: cea din 1782, a lui Iosif Zugravul, peste care s-a suprapus aproape în întregime, în 1810, decorul meșterilor Ioan din Poiana Sibiului și Mihai Borșoș."],"facts":[{"label":"Datare","value":"cca. 1600"},{"label":"Turn","value":"14 m — cel mai înalt dintre bisericile de lemn hunedorene"},{"label":"Pictură","value":"1782 (Iosif Zugravul) și 1810"},{"label":"Localizare","value":"satul Ciungani, comuna Vața de Jos"},{"label":"Cod LMI","value":"HD-II-m-A-03297"}]},"en":{"name":"Wooden Church, Ciungani","tagline":"A wooden church from around 1600, with the tallest tower of any wooden church in Hunedoara county — 14 m.","description":["On Zapoza hill in the village of Ciungani, in the Zarand Country, stands the wooden Church of the Annunciation, built by tradition around 1600 — a date its archaic plan supports. In 1755 it was described as “wooden, old, unconsecrated”. The steep roof and the 14 m spire of its bell tower — the tallest among the county's wooden churches — are covered in shingles.","Inside there are two layers of murals: those painted in 1782 by Iosif the Painter, almost entirely covered in 1810 by the work of Ioan of Poiana Sibiului and Mihai Borșoș."],"facts":[{"label":"Date","value":"c. 1600"},{"label":"Tower","value":"14 m — the tallest of Hunedoara's wooden churches"},{"label":"Murals","value":"1782 (Iosif the Painter) and 1810"},{"label":"Location","value":"Ciungani village, Vața de Jos commune"},{"label":"LMI code","value":"HD-II-m-A-03297"}]}},{"id":"biserica-de-lemn-birtin","name":"Biserica de lemn din Birtin","category":{"ro":"Biserică de lemn","en":"Wooden church"},"area":"Vața de Jos","townId":"vata-de-jos","coords":[46.17333,22.64139],"hasReviews":true,"season":"tot-anul","images":["images/biserica-de-lemn-birtin.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Birtin_4.jpg"},"ro":{"tagline":"Biserică de lemn din 1690, „în zilele lui Apafi Mihai craiu din Ardeal”, cu icoane de Stan Zugravul.","description":["Biserica de lemn „Buna Vestire” din Birtin stă pe unul dintre dealurile molcome ale satului. Inscripția săpată deasupra intrării spre naos spune: „Făcutu-s-au această sfântă biserică în zilele lui Apafi Mihaiu craiu din Ardeal, anul Domnului 1690, meseța aprilie 20 zile, popa Lazăr”. Bârnele masive ale pereților sunt așezate direct pe pământ și îmbinate în coadă de rândunică.","Ușile împărătești, cu Buna Vestire și evangheliștii, au fost pictate în 1740 de Gligorie Moldovan, iar în 1772 Stan Zugravul, fiul popii Radu din Rășinari, a realizat registrul împărătesc al iconostasului. Pereții au primit o nouă pictură în prima jumătate a secolului al XIX-lea."],"facts":[{"label":"Construită","value":"1690"},{"label":"Hram","value":"Buna Vestire"},{"label":"Pictură","value":"uși împărătești 1740; iconostas 1772 (Stan Zugravul)"},{"label":"Localizare","value":"satul Birtin, comuna Vața de Jos"},{"label":"Cod LMI","value":"HD-II-m-A-03256"}]},"en":{"name":"Wooden Church, Birtin","tagline":"A wooden church from 1690, “in the days of Michael Apafi, king of Transylvania”, with icons by Stan the Painter.","description":["The wooden Church of the Annunciation in Birtin stands on one of the village's gentle hills. The inscription cut above the door to the nave reads: “This holy church was made in the days of Michael Apafi, king of Transylvania, in the year of the Lord 1690, the 20th day of April, priest Lazăr”. The massive wall logs rest directly on the ground and are joined with dovetails.","The royal doors, with the Annunciation and the Evangelists, were painted in 1740 by Gligorie Moldovan, and in 1772 Stan the Painter, son of the priest Radu of Rășinari, painted the iconostasis's row of main icons. The walls were repainted in the first half of the 19th century."],"facts":[{"label":"Built","value":"1690"},{"label":"Dedication","value":"The Annunciation"},{"label":"Painting","value":"royal doors 1740; iconostasis 1772 (Stan the Painter)"},{"label":"Location","value":"Birtin village, Vața de Jos commune"},{"label":"LMI code","value":"HD-II-m-A-03256"}]}},{"id":"castelul-kendeffy","name":"Castelul Kendeffy","category":{"ro":"Castel","en":"Castle"},"area":"Sântămăria-Orlea","townId":"santamaria-orlea","coords":[45.588959,22.966424],"hasReviews":true,"season":"tot-anul","images":["images/castelul-kendeffy.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:CastelulKendeffy_(10).JPG"},"ro":{"tagline":"Castelul neogotic al familiei Kendeffy din 1782, fost hotel, azi închis — se poate privi doar din afară.","description":["Castelul din Sântămăria-Orlea a fost construit în 1782 de contele Elek Kendeffy, pe locul unui conac mai vechi, ca reședință a familiei în Țara Hațegului. La începutul secolului al XIX-lea i s-a adăugat un manej, iar în a doua jumătate a secolului Árpád Kendeffy l-a transformat în stil neogotic, după planurile arhitectului József Schulz, cu decorațiile lui Ferenc Storno. Pe fațadă se vede o placă barocă cu blazoanele familiilor Kendeffy și Bethlen și o inscripție latină din 1782.","După naționalizare a găzduit tabere de vară pentru copii, iar în anii 1980 a fost transformat în hotel. După 1990 a fost retrocedat urmașilor familiei, dar a rămas nefolosit: în 2024 era închis de aproape două decenii. Castelul nu se vizitează; se poate vedea din drum."],"facts":[{"label":"Construit","value":"1782, de contele Elek Kendeffy"},{"label":"Stil","value":"gotic, transformat neogotic în a doua jumătate a sec. XIX"},{"label":"Stare","value":"închis, nu se vizitează (proprietate privată)"},{"label":"Localizare","value":"satul Sântămăria-Orlea"},{"label":"Cod LMI","value":"HD-II-a-A-03446"}]},"en":{"name":"Kendeffy Castle","tagline":"The Kendeffy family's neo-Gothic castle from 1782, a former hotel, now closed — it can only be seen from outside.","description":["The castle in Sântămăria-Orlea was built in 1782 by Count Elek Kendeffy, on the site of an older manor, as the family's residence in the Hațeg Country. A riding hall was added in the early 19th century, and in the second half of that century Árpád Kendeffy had it remodelled in neo-Gothic style to plans by architect József Schulz, with decoration by Ferenc Storno. The façade bears a Baroque plaque with the Kendeffy and Bethlen coats of arms and a Latin inscription from 1782.","After nationalisation it hosted children's summer camps, and in the 1980s it became a hotel. After 1990 it was returned to the family's heirs but has stayed unused: in 2024 it had been closed for nearly two decades. The castle is not open to visitors; it can be seen from the road."],"facts":[{"label":"Built","value":"1782, by Count Elek Kendeffy"},{"label":"Style","value":"Gothic, remodelled neo-Gothic in the late 19th century"},{"label":"Status","value":"closed, not open to visitors (private property)"},{"label":"Location","value":"Sântămăria-Orlea village"},{"label":"LMI code","value":"HD-II-a-A-03446"}]}},{"id":"biserica-sanpetru","name":"Biserica „Sfântul Gheorghe” din Sânpetru","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Sântămăria-Orlea","townId":"santamaria-orlea","coords":[45.5515,22.912154],"hasReviews":true,"season":"tot-anul","images":["images/biserica-sanpetru.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:SanpetruHD_(50).JPG"},"ro":{"tagline":"Biserică cnezială din secolul al XIV-lea, cu pietre romane și un bust antic încastrate în fațadă.","description":["Biserica „Sfântul Gheorghe” din Sânpetru (comuna Sântămăria-Orlea) este unul dintre cele mai vechi monumente de zid ale românilor din Transilvania. Are o navă dreptunghiulară de 9 × 5,8 m și un altar boltit în cruce, fără turn-clopotniță, iar pe fațada de vest constructorii au încastrat câteva piese de piatră romane și un bust antic, care îi dau o înfățișare neobișnuită.","Ctitorul a fost unul dintre cnezii locali — poate Dan, tatăl lui Ștefan, jurat al Țării Hațegului între 1411 și 1418 —, deci biserica e anterioară anului 1443, când satul a fost împărțit între Cândeștii din Râu de Mori și nobilii din Unciuc și Săcel. Portalul vestic, cu arc frânt, e gotic. Sânpetru e și punctul de plecare al Văii Dinozaurilor din Geoparcul Țara Hațegului."],"facts":[{"label":"Datare","value":"sec. XIV (înainte de 1443)"},{"label":"Particularitate","value":"piese romane și un bust antic în fațada de vest"},{"label":"Plan","value":"navă 9 × 5,8 m, altar boltit în cruce, fără turn"},{"label":"Localizare","value":"satul Sânpetru, comuna Sântămăria-Orlea"},{"label":"Cod LMI","value":"HD-II-m-A-03444"}]},"en":{"name":"St George's Church, Sânpetru","tagline":"A 14th-century knez church with Roman stones and an ancient bust set into its façade.","description":["St George's Church in Sânpetru (Sântămăria-Orlea commune) is one of the oldest Romanian stone monuments in Transylvania. It has a 9 × 5.8 m rectangular nave and a cross-vaulted altar, with no bell tower, and its builders set several Roman stone pieces and an ancient bust into the west façade, giving it an unusual look.","It was founded by one of the local knezes — perhaps Dan, father of Ștefan, a juror of the Hațeg Country between 1411 and 1418 — so it predates 1443, when the village was divided between the Cândeas of Râu de Mori and the nobles of Unciuc and Săcel. The pointed-arch west portal is Gothic. Sânpetru is also the starting point of the Dinosaur Valley in the Hațeg Country Geopark."],"facts":[{"label":"Date","value":"14th century (before 1443)"},{"label":"Notable","value":"Roman pieces and an ancient bust in the west façade"},{"label":"Plan","value":"9 × 5.8 m nave, cross-vaulted altar, no tower"},{"label":"Location","value":"Sânpetru village, Sântămăria-Orlea commune"},{"label":"LMI code","value":"HD-II-m-A-03444"}]}},{"id":"biserica-trestia","name":"Biserica „Buna Vestire” din Trestia","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Băița","townId":"baita","coords":[46.02389,22.93333],"hasReviews":true,"season":"tot-anul","images":["images/biserica-trestia.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_Buna_Vestire_din_Trestia_(4).jpg"},"ro":{"tagline":"Biserică masivă de piatră din 1674, ctitorită de nobilul Francisc Gyulay, proprietar de mine, cu un iconostas brâncovenesc.","description":["Pe un pinten de munte de la marginea satului Trestia (comuna Băița), atestat în 1439, s-a ridicat în 1674 o biserică mare de piatră, închinată Bunei Vestiri. Ctitorul a fost nobilul Francisc Gyulay, comandant în armata habsburgică și mare proprietar de mine, care în 1690 i-a dăruit două clopote și un steag primit de la împăratul Leopold I.","Iconostasul, de la începutul secolului al XVIII-lea, are motive sculptate de influență brâncovenească; registrul împărătesc e atribuit lui Simion Silaghi din Abrud, iar icoana de hram și cele douăsprezece praznicare meșterului Iacob din Rășinari. Pictura murală anonimă, din a doua jumătate a secolului al XVIII-lea, acoperă doar pronaosul și exonartexul."],"facts":[{"label":"Construită","value":"1674"},{"label":"Ctitor","value":"Francisc Gyulay, proprietar de mine"},{"label":"Iconostas","value":"începutul sec. XVIII, de influență brâncovenească"},{"label":"Localizare","value":"satul Trestia, comuna Băița"},{"label":"Cod LMI","value":"HD-II-m-A-03469"}]},"en":{"name":"Church of the Annunciation, Trestia","tagline":"A massive stone church from 1674, founded by the mine-owning noble Francis Gyulay, with a Brâncoveanu-style iconostasis.","description":["On a mountain spur at the edge of Trestia (Băița commune), recorded in 1439, a large stone church dedicated to the Annunciation was built in 1674. Its founder was the noble Francis Gyulay, a commander in the Habsburg army and a major mine owner, who in 1690 gave it two bells and a banner received from Emperor Leopold I.","The early 18th-century iconostasis has carved motifs in the Brâncoveanu style; its row of main icons is attributed to Simion Silaghi of Abrud, and the patronal icon and twelve feast icons to Master Iacob of Rășinari. Anonymous murals from the second half of the 18th century cover only the narthex and the outer porch."],"facts":[{"label":"Built","value":"1674"},{"label":"Founder","value":"Francis Gyulay, mine owner"},{"label":"Iconostasis","value":"early 18th century, Brâncoveanu style"},{"label":"Location","value":"Trestia village, Băița commune"},{"label":"LMI code","value":"HD-II-m-A-03469"}]}},{"id":"biserica-lesnic","name":"Biserica „Sfântul Nicolae” din Leșnic","category":{"ro":"Monument istoric","en":"Historic monument"},"area":"Vețel","townId":"vetel","coords":[45.91361,22.74167],"hasReviews":true,"season":"tot-anul","images":["images/biserica-lesnic.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Lesnic_29.jpg"},"ro":{"tagline":"Mică biserică cnezială de la sfârșitul secolului al XIV-lea, cu pictură medievală în naos.","description":["Biserica de zid „Sfântul Nicolae” din Leșnic, comuna Vețel, pe malul stâng al Mureșului, este una dintre vechile ctitorii ale cnezilor români din părțile Hunedoarei. Are un plan simplu, de tip sală: un naos de 5,6 × 5 m și un altar boltit, la care s-a adăugat mai târziu un pronaos cu clopotniță de lemn și un mic pridvor.","Pe baza arhitecturii și a picturii din naos, biserica a fost datată la sfârșitul secolului al XIV-lea sau începutul secolului al XV-lea. Ctitorul e considerat cneazul Dobre, fiul lui Ioan din Leșnic, care în 1386 era întărit în stăpânirea unui munte de la izvoarele văii Leșnicului. Săpăturile din 1984 au însoțit restaurarea monumentului."],"facts":[{"label":"Datare","value":"sfârșitul sec. XIV – începutul sec. XV"},{"label":"Ctitor","value":"probabil cneazul Dobre din Leșnic"},{"label":"Pictură","value":"medievală, în naos"},{"label":"Localizare","value":"satul Leșnic, comuna Vețel"},{"label":"Cod LMI","value":"HD-II-m-A-03359"}]},"en":{"name":"St Nicholas' Church, Leșnic","tagline":"A small knez church from the late 14th century, with medieval murals in the nave.","description":["St Nicholas' stone church in Leșnic, Vețel commune, on the left bank of the Mureș, is one of the old foundations of Romanian knezes in the Hunedoara area. It has a simple hall plan: a 5.6 × 5 m nave and a vaulted altar, later extended with a narthex topped by a wooden bell tower and a small porch.","Its architecture and the murals in the nave date it to the late 14th or early 15th century. Its founder is thought to be the knez Dobre, son of Ioan of Leșnic, who in 1386 was confirmed in possession of a mountain at the head of the Leșnic valley. Excavations in 1984 accompanied the building's restoration."],"facts":[{"label":"Date","value":"late 14th – early 15th century"},{"label":"Founder","value":"probably the knez Dobre of Leșnic"},{"label":"Murals","value":"medieval, in the nave"},{"label":"Location","value":"Leșnic village, Vețel commune"},{"label":"LMI code","value":"HD-II-m-A-03359"}]}},{"id":"castelul-gyulay-mintia","name":"Castelul Gyulay din Mintia","category":{"ro":"Castel","en":"Castle"},"area":"Vețel","townId":"vetel","coords":[45.924965,22.856363],"hasReviews":true,"season":"tot-anul","images":["images/castelul-gyulay-mintia.jpg"],"photoCredit":{"author":"Leszay izabella","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Mintia_Castelu_Gyulai_Ferencz.jpg"},"ro":{"tagline":"Castel al familiei Gyulay din 1641, refăcut în stil clasicist în 1834, într-un parc de 5 hectare pe malul Mureșului.","description":["Familia Gyulay și-a construit castelul de la Mintia, pe malul stâng al Mureșului, în 1641. Contele Lajos Gyulay l-a transformat în 1834 în stil clasicist, după planurile arhitectului Stuller; fațada principală are arcade, iar din galeria din spate se deschide priveliștea spre parc. Ansamblul, castelul și parcul de circa 5 ha, e monument istoric.","Castelul a fost devastat în răscoala din 1784 și în 1848–1849. Aici a trăit Lajos Gyulay, autorul unuia dintre cele mai lungi jurnale personale din literatura maghiară, iar mai târziu istoricul și orientalistul Géza Kuun, care a strâns aici o bibliotecă și o arhivă bogate. În 2007 a fost retrocedat moștenitorilor; e proprietate privată și se poate vedea din afară."],"facts":[{"label":"Construit","value":"1641; refăcut clasicist în 1834"},{"label":"Parc","value":"cca. 5 ha"},{"label":"Personalități","value":"Lajos Gyulay (memorialist), Géza Kuun (orientalist)"},{"label":"Stare","value":"proprietate privată, se vede din exterior"},{"label":"Cod LMI","value":"HD-II-a-A-03366"}]},"en":{"name":"Gyulay Castle, Mintia","tagline":"The Gyulay family's castle from 1641, rebuilt in Classicist style in 1834, in a 5-hectare park by the Mureș.","description":["The Gyulay family built their castle at Mintia, on the left bank of the Mureș, in 1641. Count Lajos Gyulay had it remodelled in Classicist style in 1834 to plans by the architect Stuller; the main façade is arcaded, and the rear gallery looks out over the park. The castle and its park of about 5 ha are listed together as a historic monument.","The castle was ransacked during the 1784 uprising and again in 1848–1849. It was home to Lajos Gyulay, author of one of the longest private diaries in Hungarian literature, and later to the historian and orientalist Géza Kuun, who built up a rich library and archive here. It was returned to the heirs in 2007; it is private property and can be seen from outside."],"facts":[{"label":"Built","value":"1641; remodelled in Classicist style in 1834"},{"label":"Park","value":"about 5 ha"},{"label":"Notable people","value":"Lajos Gyulay (diarist), Géza Kuun (orientalist)"},{"label":"Status","value":"private property, seen from outside"},{"label":"LMI code","value":"HD-II-a-A-03366"}]}},{"id":"biserica-beriu","name":"Biserica „Adormirea Maicii Domnului” din Beriu","category":{"ro":"Biserică","en":"Church"},"area":"Beriu","townId":"beriu","coords":[45.7903,23.191],"hasReviews":true,"season":"tot-anul","images":["images/biserica-beriu.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_Adormirea_Maicii_Domnuuli_din_Beriu_(1).jpg"},"ro":{"tagline":"Biserica satului Beriu, refăcută în 1894–1897 după un incendiu, cu turn masiv cu coif baroc.","description":["Beriu, satul de reședință al comunei, e atestat documentar din 1332; aici, ca și la Sereca, au fost colonizați sași în 1334. Biserica ortodoxă „Adormirea Maicii Domnului” a fost reconstruită între 1894 și 1897 de arhitectul Nicolae Părău din Orăștie, după ce biserica de piatră din secolul al XVIII-lea — pictată în 1793, probabil de zugravul local Ioan din Beriu — fusese grav afectată de un incendiu în vara lui 1894.","Are plan dreptunghiular, cu absida poligonală, iar deasupra intrării de vest se ridică un turn masiv cu coif de inspirație barocă. Pictura interioară e din 1898–1899 și a fost reînnoită în 2000–2003 de Ligia Despina Crăciunescu."],"facts":[{"label":"Reconstruită","value":"1894–1897 (arh. Nicolae Părău, Orăștie)"},{"label":"Pictură","value":"1898–1899, reînnoită în 2000–2003"},{"label":"Biserica veche","value":"de piatră, sec. XVIII, afectată de incendiul din 1894"},{"label":"Localizare","value":"satul Beriu, comuna Beriu"}]},"en":{"name":"Church of the Dormition, Beriu","tagline":"Beriu's village church, rebuilt in 1894–1897 after a fire, with a massive tower and a Baroque-style cap.","description":["Beriu, the commune's seat, is recorded from 1332; Saxons were settled here, as at Sereca, in 1334. The Orthodox Church of the Dormition was rebuilt between 1894 and 1897 by the Orăștie architect Nicolae Părău, after the 18th-century stone church — painted in 1793, probably by the local painter Ioan of Beriu — was badly damaged by a fire in the summer of 1894.","It has a rectangular plan with a polygonal apse, and a massive tower with a Baroque-inspired cap rises above the west entrance. The interior was painted in 1898–1899 and repainted in 2000–2003 by Ligia Despina Crăciunescu."],"facts":[{"label":"Rebuilt","value":"1894–1897 (architect Nicolae Părău, Orăștie)"},{"label":"Murals","value":"1898–1899, renewed 2000–2003"},{"label":"Earlier church","value":"stone, 18th century, damaged by the 1894 fire"},{"label":"Location","value":"Beriu village, Beriu commune"}]}},{"id":"biserica-castau","name":"Biserica „Sfinții Arhangheli” din Căstău","category":{"ro":"Biserică","en":"Church"},"area":"Beriu","townId":"beriu","coords":[45.8135,23.2112],"hasReviews":true,"season":"tot-anul","images":["images/biserica-castau.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_Sfin%C8%9Bii_Arhangheli_din_C%C4%83st%C4%83u_(1).jpg"},"ro":{"tagline":"Biserică mare de zid ridicată în 1868–1874 în satul Căstău, pe locul unei bisericuțe din secolul al XVIII-lea.","description":["Căstău, sat al comunei Beriu, are o biserică de mari dimensiuni, închinată Sfinților Arhangheli Mihail și Gavriil, construită între 1868 și 1874, pe vremea preoților Aron și Ioan Dănilă. Ea a urmat unei bisericuțe de zid pomenite în conscripțiile din 1733, 1750, 1761–1762, 1805 și 1829–1831.","Are altar semicircular, o navă spațioasă împărțită în naos și pronaos și un turn-clopotniță pătrat deasupra intrării de vest. A fost renovată în 1921–1925, 1965, 1990 și 2005. Din fosta biserică greco-catolică a satului, ridicată din piatră în 1836, se mai vede azi doar fundația."],"facts":[{"label":"Construită","value":"1868–1874"},{"label":"Hram","value":"Sfinții Arhangheli Mihail și Gavriil"},{"label":"Renovări","value":"1921–1925, 1965, 1990, 2005"},{"label":"Localizare","value":"satul Căstău, comuna Beriu"}]},"en":{"name":"Church of the Holy Archangels, Căstău","tagline":"A large stone church built in 1868–1874 in the village of Căstău, on the site of an 18th-century chapel.","description":["Căstău, a village of Beriu commune, has a large church dedicated to the Archangels Michael and Gabriel, built between 1868 and 1874 under the priests Aron and Ioan Dănilă. It replaced a small stone church recorded in the church censuses of 1733, 1750, 1761–1762, 1805 and 1829–1831.","It has a semicircular altar, a spacious nave divided into naos and narthex, and a square bell tower above the west entrance. It was renovated in 1921–1925, 1965, 1990 and 2005. Of the village's former Greek Catholic church, built of stone in 1836, only the foundation can still be seen."],"facts":[{"label":"Built","value":"1868–1874"},{"label":"Dedication","value":"Archangels Michael and Gabriel"},{"label":"Renovations","value":"1921–1925, 1965, 1990, 2005"},{"label":"Location","value":"Căstău village, Beriu commune"}]}},{"id":"cetatea-costesti-blidaru","name":"Cetatea Costești-Blidaru","category":{"ro":"Cetate dacică","en":"Dacian fortress"},"area":"Munții Orăștiei","townId":"orastioara-de-sus","coords":[45.6678,23.1629],"hasReviews":true,"season":"tot-anul","images":["images/cetatea-blidaru.jpg"],"photoCredit":{"author":"Oroles","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Blidaru.JPG"},"ro":{"tagline":"Cel mai puternic complex fortificat dintre cetățile dacice din Munții Orăștiei, pe culmea Blidarului, în patrimoniul mondial UNESCO.","description":["Cetatea dacică Costești-Blidaru se află lângă satul Costești, comuna Orăștioara de Sus, pe culmea Blidarului (750 m), pe malul stâng al apei Grădiștei. A fost construită în secolul I î.Hr., ca apărare în fața cuceririi romane, și este una dintre cele șase fortărețe dacice din Munții Orăștiei înscrise în patrimoniul mondial UNESCO.","Este cel mai puternic complex fortificat din zonă: se întinde pe un platou de aproape 6000 mp și cuprinde două incinte unite între ele, cu șase turnuri în total. Prima cetate, de formă trapezoidală, ocupă platoul superior și are patru turnuri exterioare, pe colțuri; intrarea se făcea prin turnul I, gândit astfel încât atacatorii să fie siliți să cotească și să-și expună flancul. A doua incintă, pentagonală, a fost ridicată la vest de prima."],"facts":[{"label":"Datare","value":"secolul I î.Hr."},{"label":"Altitudine","value":"750 m (culmea Blidarului)"},{"label":"Componente","value":"două incinte, șase turnuri, platou de aproape 6000 mp"},{"label":"Statut","value":"patrimoniu mondial UNESCO (Fortărețele dacice din Munții Orăștiei)"},{"label":"Localizare","value":"lângă satul Costești, comuna Orăștioara de Sus"}]},"en":{"name":"Costești-Blidaru Fortress","tagline":"The strongest fortified complex among the Dacian fortresses of the Orăștie Mountains, on Blidaru ridge, part of UNESCO World Heritage.","description":["The Dacian fortress of Costești-Blidaru stands near the village of Costești, Orăștioara de Sus commune, on Blidaru ridge (750 m), on the left bank of the Grădiște stream. It was built in the 1st century BC as a defence against the Roman conquest and is one of the six Dacian fortresses of the Orăștie Mountains inscribed on the UNESCO World Heritage List.","It is the strongest fortified complex in the area: it spreads over a plateau of almost 6,000 sq m and has two linked enclosures with six towers in all. The first fortress, trapezoidal, occupies the upper plateau and has four outer towers at its corners; the entrance went through tower I, designed so that attackers had to turn and expose their flank. The second, pentagonal enclosure was built to the west of the first."],"facts":[{"label":"Dating","value":"1st century BC"},{"label":"Altitude","value":"750 m (Blidaru ridge)"},{"label":"Components","value":"two enclosures, six towers, a plateau of almost 6,000 sq m"},{"label":"Status","value":"UNESCO World Heritage (Dacian Fortresses of the Orăștie Mountains)"},{"label":"Location","value":"near Costești village, Orăștioara de Sus commune"}]}},{"id":"cetatea-costesti-cetatuie","name":"Cetatea Costești-Cetățuie","category":{"ro":"Cetate dacică","en":"Dacian fortress"},"area":"Munții Orăștiei","townId":"orastioara-de-sus","coords":[45.6794,23.1541],"hasReviews":true,"season":"tot-anul","images":["images/cetatea-costesti-cetatuie.jpg"],"photoCredit":{"author":"Oroles","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Costesti.JPG"},"ro":{"tagline":"Fortăreață dacică pe valea Apei Grădiștei, reședință a regilor daci și pază a drumului spre Sarmizegetusa Regia.","description":["Cetățuia Costești se află pe valea Apei Grădiștei, lângă satul Costești (comuna Orăștioara de Sus); platoul superior al dealului are 514 m altitudine. Era o cetate puternică, cu rol defensiv, la baza căreia se întindea o mare așezare civilă, și reședința obișnuită a regilor daci transilvăneni. Un alt rol al ei era apărarea drumului spre cetatea Sarmizegetusa Regia.","Primul sistem defensiv a fost un val de pământ lat de 6–8 m la bază și înalt astăzi de 2–2,5 m, în care erau înfipți stâlpi groși de lemn, legați între ei cu împletituri de nuiele lipite cu pământ — o palisadă în spatele căreia se adăposteau apărătorii. Cetatea face parte din cele șase fortărețe dacice din Munții Orăștiei înscrise în patrimoniul mondial UNESCO."],"facts":[{"label":"Datare","value":"secolul I î.Hr."},{"label":"Altitudine","value":"514 m (platoul superior)"},{"label":"Rol","value":"reședință regală; apărarea drumului spre Sarmizegetusa Regia"},{"label":"Apărare","value":"val de pământ cu palisadă de lemn"},{"label":"Localizare","value":"valea Apei Grădiștei, lângă satul Costești"}]},"en":{"name":"Costești-Cetățuie Fortress","tagline":"A Dacian fortress in the Grădiște valley, a seat of the Dacian kings that guarded the road to Sarmizegetusa Regia.","description":["Costești-Cetățuie stands in the Grădiște valley near the village of Costești (Orăștioara de Sus commune); the upper plateau of the hill is 514 m high. It was a strong defensive fortress with a large civilian settlement at its foot, and the usual residence of the Transylvanian Dacian kings. Another of its roles was to protect the road to the fortress of Sarmizegetusa Regia.","The first line of defence was an earth rampart 6–8 m wide at the base and 2–2.5 m high today, in which thick wooden posts were set, bound together with wattle daubed with clay — a palisade behind which the defenders sheltered. The fortress is one of the six Dacian fortresses of the Orăștie Mountains inscribed on the UNESCO World Heritage List."],"facts":[{"label":"Dating","value":"1st century BC"},{"label":"Altitude","value":"514 m (upper plateau)"},{"label":"Role","value":"royal residence; guarding the road to Sarmizegetusa Regia"},{"label":"Defences","value":"earth rampart with a wooden palisade"},{"label":"Location","value":"Grădiște valley, near Costești village"}]}},{"id":"castrul-roman-micia","name":"Castrul roman Micia","category":{"ro":"Castru roman","en":"Roman fort"},"area":"Vețel","townId":"vetel","coords":[45.9146,22.8149],"hasReviews":true,"season":"tot-anul","images":["images/castrul-roman-micia.jpg"],"photoCredit":{"author":"Saturnian","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Castra_Micia_043.jpg"},"ro":{"tagline":"Ruinele unui mare castru și ale unei așezări romane cu rețea stradală, terme, amfiteatru și port, pe malul Mureșului.","description":["Micia a fost o importantă așezare romană, dezvoltată în jurul unui mare castru. Ruinele se află astăzi pe teritoriul satului Vețel, pe malul stâng al Mureșului, în dreptul termocentralei de la Mintia.","Deși avea doar statut rural (pagus), așezarea era puternic urbanizată: rețea stradală ortogonală, edificii publice monumentale — terme, amfiteatru — și un port la Mureș, amenajat cu cheiuri din zidărie de piatră. Pe la 1840, în ruine a fost găsit un altar votiv din secolele II–III, închinat zeului Silvanus Domesticus, care arată cum erau administrate pășunile și salinele din Dacia romană."],"facts":[{"label":"Epoca","value":"romană (Dacia romană)"},{"label":"Localizare","value":"satul Vețel, pe malul stâng al Mureșului, în dreptul termocentralei Mintia"},{"label":"Urme","value":"rețea stradală ortogonală, terme, amfiteatru, port cu cheiuri de piatră"},{"label":"Descoperire","value":"altar votiv din sec. II–III, dedicat lui Silvanus Domesticus"}]},"en":{"name":"Micia Roman Fort","tagline":"The ruins of a large fort and a Roman settlement with a street grid, baths, amphitheatre and port, on the Mureș bank.","description":["Micia was an important Roman settlement that grew around a large fort. Its ruins now lie in the village of Vețel, on the left bank of the Mureș, opposite the Mintia power plant.","Although it only had rural status (a pagus), the settlement was highly urbanised: an orthogonal street grid, monumental public buildings — baths, an amphitheatre — and a port on the Mureș, fitted with stone-masonry quays. Around 1840 a votive altar of the 2nd–3rd century, dedicated to the god Silvanus Domesticus, was found in the ruins; it shows how pastures and salt mines were administered in Roman Dacia."],"facts":[{"label":"Period","value":"Roman (Roman Dacia)"},{"label":"Location","value":"Vețel village, on the left bank of the Mureș, opposite the Mintia power plant"},{"label":"Remains","value":"orthogonal street grid, baths, amphitheatre, port with stone quays"},{"label":"Find","value":"votive altar of the 2nd–3rd century, dedicated to Silvanus Domesticus"}]}},{"id":"castrul-roman-germisara","name":"Castrul roman Germisara (Cigmău)","category":{"ro":"Castru roman","en":"Roman fort"},"area":"Geoagiu","townId":"geoagiu","coords":[45.897,23.1644],"hasReviews":true,"season":"tot-anul","relatedIds":["termele-romane-germisara"],"images":["images/castrul-roman-germisara.jpg"],"photoCredit":{"author":"Saturnian","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Castra_of_Cigmau_-_26.JPG"},"ro":{"tagline":"Castru auxiliar roman lângă Geoagiu, cunoscut local drept „Cetatea Uriașului”, cu o așezare civilă alături.","description":["Castrul roman Germisara, numit și castrul de la Cigmău, a fost un castru de trupe auxiliare, cu o așezare civilă alături. Situl arheologic — cunoscut local drept „Cetatea Uriașului” sau „Cetatea Urieșilor” — se află pe platoul Turiac, prima terasă a Mureșului, la circa 2 km de Geoagiu spre Simeria, în satul Cigmău, pe malul drept al Mureșului.","Germisara este atestată în Tabula Peutingeriana, în Geografia lui Ptolemeu și în Cosmografia de la Ravenna. Până în 1990 terenul a fost lucrat agricol, ceea ce a distrus parțial sau total zidurile, iar piatra a fost luată de localnicii din așezările apropiate; săpăturile arheologice au început abia în anul 2000."],"facts":[{"label":"Epoca","value":"romană"},{"label":"Tip","value":"castru de trupe auxiliare, cu așezare civilă"},{"label":"Localizare","value":"platoul Turiac, satul Cigmău, la ~2 km de Geoagiu spre Simeria"},{"label":"Atestare","value":"Tabula Peutingeriana, Ptolemeu, Cosmografia de la Ravenna"}]},"en":{"name":"Germisara Roman Fort (Cigmău)","tagline":"A Roman auxiliary fort near Geoagiu, known locally as the “Giant's Fortress”, with a civilian settlement beside it.","description":["The Roman fort of Germisara, also called the Cigmău fort, was a fort for auxiliary troops with a civilian settlement alongside. The archaeological site — known locally as the “Giant's Fortress” — lies on the Turiac plateau, the first terrace of the Mureș, about 2 km from Geoagiu towards Simeria, in the village of Cigmău, on the right bank of the Mureș.","Germisara is recorded in the Tabula Peutingeriana, in Ptolemy's Geography and in the Ravenna Cosmography. Until 1990 the land was farmed, which partly or wholly destroyed the walls, and the stone was taken by people from nearby villages; archaeological digs began only in 2000."],"facts":[{"label":"Period","value":"Roman"},{"label":"Type","value":"fort for auxiliary troops, with a civilian settlement"},{"label":"Location","value":"Turiac plateau, Cigmău village, ~2 km from Geoagiu towards Simeria"},{"label":"Sources","value":"Tabula Peutingeriana, Ptolemy, Ravenna Cosmography"}]}},{"id":"panteonul-motilor-tebea","name":"Panteonul Moților din Țebea","category":{"ro":"Complex memorial","en":"Memorial complex"},"area":"Țara Zarandului","townId":"baia-de-cris","coords":[46.1681,22.7358],"hasReviews":true,"season":"tot-anul","images":["images/panteonul-motilor-tebea.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Tebea_2011.21.jpg"},"ro":{"tagline":"Cimitirul eroilor din Țebea, cu mormântul lui Avram Iancu și celebrul Gorun al lui Horea.","description":["Panteonul Moților este numele sub care se cunoaște Cimitirul eroilor din Țebea, un complex memorial aflat lângă drumul european E79. Aici se găsesc biserica satului, mormintele revoluționarilor de la 1848 Avram Iancu, Ioan Buteanu și Simeon Groza, morminte și cruci ale eroilor din Războiul de Independență și din cele două războaie mondiale, precum și Gorunul lui Horea. Țebea este considerat capitala Țării Zarandului.","Ansamblul se află pe o movilă, în jurul bisericii. La circa 15 m vest de biserică este mormântul lui Avram Iancu, socotit centrul complexului, iar la sud de el stă Gorunul lui Horea — de fapt un stejar pedunculat de circa 400 de ani, cu circumferința de 9 m. Potrivit tradiției, sub acest copac Horea i-a chemat la luptă pe moții adunați, în 1784.","Trunchiul, slăbit în timp, a fost legat cu cercuri de oțel în 1924, iar la restaurarea din 1947 a fost îmbrăcat în ciment, cu modelul scoarței realizat de sculptorul Radu Moga-Mânzat."],"facts":[{"label":"Localizare","value":"satul Țebea, comuna Baia de Criș, lângă drumul european E79"},{"label":"Morminte","value":"Avram Iancu (†10 septembrie 1872), Ioan Buteanu, Simeon Groza"},{"label":"Gorunul lui Horea","value":"stejar pedunculat de ~400 de ani, circumferință 9 m"},{"label":"Istorie","value":"legat cu cercuri de oțel în 1924; acoperit cu ciment la restaurarea din 1947"}]},"en":{"name":"Moților Pantheon, Țebea","tagline":"The heroes' cemetery in Țebea, with Avram Iancu's grave and the famous Horea's Oak.","description":["The Moților Pantheon (Pantheon of the Moți) is the name by which the Heroes' Cemetery of Țebea is known, a memorial complex beside the E79 European road. It holds the village church, the graves of the 1848 revolutionaries Avram Iancu, Ioan Buteanu and Simeon Groza, graves and crosses of heroes of the War of Independence and the two world wars, and Horea's Oak. Țebea is regarded as the capital of the Zarand Country.","The complex stands on a mound, around the church. About 15 m west of the church is Avram Iancu's grave, considered the centre of the complex, and south of it stands Horea's Oak — in fact a pedunculate oak about 400 years old, with a 9 m circumference. According to tradition, it was under this tree that Horea called the assembled Moți to arms in 1784.","The trunk, weakened over time, was bound with steel hoops in 1924 and, during the 1947 restoration, covered in cement, with the bark pattern modelled by the sculptor Radu Moga-Mânzat."],"facts":[{"label":"Location","value":"Țebea village, Baia de Criș commune, beside the E79 European road"},{"label":"Graves","value":"Avram Iancu (d. 10 September 1872), Ioan Buteanu, Simeon Groza"},{"label":"Horea's Oak","value":"pedunculate oak, ~400 years old, 9 m circumference"},{"label":"History","value":"bound with steel hoops in 1924; covered in cement in the 1947 restoration"}]}},{"id":"casa-memoriala-crisan","name":"Casa memorială Crișan","category":{"ro":"Casă memorială","en":"Memorial house"},"area":"Brad","townId":"ribita","coords":[46.1703,22.7996],"hasReviews":true,"season":"tot-anul","images":["images/casa-memoriala-crisan.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:CasaNatalaCrisan_(22).jpg"},"ro":{"tagline":"Casa reconstituită a lui Gheorghe Crișan, unul dintre conducătorii răscoalei țăranilor din 1784–1785.","description":["Casa natală Crișan se află în satul Crișan (numit în trecut Vaca), comuna Ribița, în nordul județului. Este monument istoric (cod LMI HD-IV-m-B-03491) și a fost reconstruită în 1979, după o fotografie publicată de istoricul Ioan Lupaș în 1934. În acest sat s-a născut Gheorghe Crișan, unul dintre conducătorii răscoalei țăranilor români din Transilvania din 1784–1785.","Clădirea reproduce o casă țărănească de la începutul secolului al XVIII-lea: fundație de piatră, două camere și o cămară din bârne de lemn, târnaț cu stâlpi și arcade și acoperiș de paie. În încăperi sunt expuse piese de etnografie din zona Ribița — inclusiv un interior de casă moțească —, arme albe și de foc din secolul al XVIII-lea și material foto-documentar despre răscoală."],"facts":[{"label":"Localizare","value":"satul Crișan (fost Vaca), comuna Ribița"},{"label":"Reconstruită","value":"1979, după o fotografie din 1934"},{"label":"Construcție","value":"fundație de piatră, pereți din bârne, acoperiș de paie"},{"label":"Cod LMI","value":"HD-IV-m-B-03491"}]},"en":{"name":"Crișan Memorial House","tagline":"The reconstructed house of Gheorghe Crișan, one of the leaders of the 1784–1785 peasant uprising.","description":["The Crișan birth house stands in the village of Crișan (formerly Vaca), Ribița commune, in the north of the county. It is a historic monument (LMI code HD-IV-m-B-03491) and was rebuilt in 1979 from a photograph published by the historian Ioan Lupaș in 1934. This village was the birthplace of Gheorghe Crișan, one of the leaders of the 1784–1785 uprising of the Romanian peasants of Transylvania.","The building reproduces an early 18th-century peasant house: a stone foundation, two rooms and a pantry of timber logs, a porch with posts and arches, and a thatched roof. Inside are ethnographic pieces from the Ribița area — including the interior of a Moți house —, 18th-century bladed and firearms, and photo-documentary material about the uprising."],"facts":[{"label":"Location","value":"Crișan village (formerly Vaca), Ribița commune"},{"label":"Rebuilt","value":"1979, from a 1934 photograph"},{"label":"Construction","value":"stone foundation, log walls, thatched roof"},{"label":"LMI code","value":"HD-IV-m-B-03491"}]}},{"id":"catedrala-ortodoxa-orastie","name":"Catedrala Ortodoxă din Orăștie","category":{"ro":"Catedrală ortodoxă","en":"Orthodox cathedral"},"area":"Orăștie","townId":"orastie","coords":[45.8376,23.1927],"hasReviews":true,"season":"tot-anul","images":["images/catedrala-orastie.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Catedrala_din_Orăștie_(4).jpg"},"ro":{"tagline":"Catedrala cu hramul Sfinții Arhangheli Mihail și Gavriil, ridicată în 1936–1943, cu turn de cinci clopote de bronz.","description":["Catedrala ortodoxă din Orăștie, cu hramul Sfinții Arhangheli Mihail și Gavriil, domină centrul orașului, în Piața Victoriei. A fost ridicată între 1936 și 1943, din inițiativa protopopului Ioan Moța — gazetar și om politic, luptător pentru Marea Unire —, cu sprijinul Băncii „Ardeleana” din Orăștie, al Băncii Naționale a României, al societății „Mica” din Brad, al Liceului „Aurel Vlaicu” și al Regimentului 92 Infanterie.","Edificiul are proporții monumentale, în plan de cruce greacă, și îmbină elemente de arhitectură bizantină, romanică și gotică; arhitectul George Cristinel a creat o clădire unică în spațiul românesc. Nota distinctivă este turnul impunător, cu cinci clopote mari de bronz, alipit peretelui nordic al pronaosului. La construcție s-au folosit beton armat și cărămidă."],"facts":[{"label":"Hram","value":"Sfinții Arhangheli Mihail și Gavriil"},{"label":"Construcție","value":"1936–1943"},{"label":"Arhitect","value":"George Cristinel"},{"label":"Plan","value":"cruce greacă; stil care îmbină elemente bizantine, romanice și gotice"},{"label":"Adresă","value":"Piața Victoriei nr. 1, Orăștie"}]},"en":{"name":"Orthodox Cathedral of Orăștie","tagline":"The cathedral dedicated to the Archangels Michael and Gabriel, built in 1936–1943, with a tower of five bronze bells.","description":["The Orthodox Cathedral of Orăștie, dedicated to the Archangels Michael and Gabriel, dominates the town centre on Victory Square. It was built between 1936 and 1943 on the initiative of Archpriest Ioan Moța — a journalist and politician, a fighter for the Great Union — with the support of the “Ardeleana” Bank of Orăștie, the National Bank of Romania, the “Mica” company of Brad, the “Aurel Vlaicu” High School and the 92nd Infantry Regiment.","The building has monumental proportions, on a Greek-cross plan, and combines Byzantine, Romanesque and Gothic elements; the architect George Cristinel created a building unique in Romania. Its distinctive feature is the imposing tower with five large bronze bells, attached to the north wall of the narthex. Reinforced concrete and brick were used in its construction."],"facts":[{"label":"Patron saints","value":"Archangels Michael and Gabriel"},{"label":"Built","value":"1936–1943"},{"label":"Architect","value":"George Cristinel"},{"label":"Plan","value":"Greek cross; a style combining Byzantine, Romanesque and Gothic elements"},{"label":"Address","value":"Piața Victoriei no. 1, Orăștie"}]}},{"id":"biserica-luterana-orastie","name":"Biserica luterană din Orăștie","category":{"ro":"Biserică luterană","en":"Lutheran church"},"area":"Orăștie","townId":"orastie","coords":[45.8373,23.1959],"hasReviews":true,"season":"tot-anul","images":["images/biserica-luterana-orastie.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:OrastieHD2012_(26).JPG"},"ro":{"tagline":"Biserica comunității săsești, construită la începutul secolului al XIX-lea în vecinătatea vechii biserici a orașului.","description":["În evul mediu, întreaga comunitate din Orăștie folosea aceeași biserică, astăzi biserica reformată. După Reforma protestantă, maghiarii din oraș au adoptat reforma lui Jean Calvin, iar sașii pe cea a lui Martin Luther. Timp de trei secole, sașii au folosit alternativ, cu maghiarii, fosta biserică romano-catolică; la începutul secolului al XIX-lea și-au construit un lăcaș nou, în imediata vecinătate a celei vechi.","Biserica este monument istoric și amintește trecutul săsesc al orașului, numit în germană Broos și în maghiară Szászváros — „Orașul sașilor”."],"facts":[{"label":"Confesiune","value":"luterană (comunitatea săsească)"},{"label":"Construcție","value":"începutul secolului al XIX-lea"},{"label":"Statut","value":"monument istoric"},{"label":"Localizare","value":"Orăștie, lângă biserica reformată"}]},"en":{"name":"Lutheran Church of Orăștie","tagline":"The church of the Saxon community, built in the early 19th century next to the town's old church.","description":["In the Middle Ages the whole community of Orăștie used the same church, today the Reformed church. After the Protestant Reformation the town's Hungarians adopted the reform of John Calvin and the Saxons that of Martin Luther. For three centuries the Saxons shared the former Roman Catholic church with the Hungarians, taking turns; in the early 19th century they built a new place of worship right next to the old one.","The church is a historic monument and recalls the Saxon past of the town, called Broos in German and Szászváros in Hungarian — “the Saxons' town”."],"facts":[{"label":"Denomination","value":"Lutheran (Saxon community)"},{"label":"Built","value":"early 19th century"},{"label":"Status","value":"historic monument"},{"label":"Location","value":"Orăștie, next to the Reformed church"}]}},{"id":"manastirea-franciscana-deva","name":"Mănăstirea franciscană din Deva","category":{"ro":"Mănăstire franciscană","en":"Franciscan monastery"},"area":"Deva","townId":"deva","coords":[45.8874,22.907],"hasReviews":true,"season":"tot-anul","images":["images/manastirea-franciscana-deva.jpg"],"photoCredit":{"author":"Dezidor","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Deva,_kostel.jpg"},"ro":{"tagline":"Mănăstire și biserică baroce din Deva, ridicate de franciscani veniți din Ciprovți și definitivate până în 1752.","description":["Mănăstirea franciscană din Deva, cu hramul Sfânta Maria, este monument istoric și de arhitectură (cod LMI HD-II-a-B-03231). A fost înființată la începutul secolului al XVIII-lea de călugări ai provinciei bulgare a Ordinului Franciscan, sprijiniți de catolicii din Ciprovți, care la sfârșitul secolului al XVII-lea au emigrat în masă în Țara Românească și Transilvania. Ansamblul a fost ridicat în etape, până în 1752.","Clădirea, în formă de patrulater, urmează stilul mănăstirilor franciscane din Transilvania, cu biserica barocă alipită colțului de sud-est; este construită din piatră și cărămidă, cu decorațiuni în relief și statuete de baroc târziu. A fost mistuită de flăcări de mai multe ori — în 1707, incendiată de trupele generalului Acton, apoi în 1748 și 1872 —, iar în 1749 biserica a fost mărită din materialul clădirilor afectate."],"facts":[{"label":"Hram","value":"Sfânta Maria"},{"label":"Stil","value":"baroc, din piatră și cărămidă"},{"label":"Incendii","value":"1707, 1748, 1872"},{"label":"Cod LMI","value":"HD-II-a-B-03231"},{"label":"Adresă","value":"Strada Progresului, Deva"}]},"en":{"name":"Franciscan Monastery of Deva","tagline":"A Baroque monastery and church in Deva, built by friars from Chiprovtsi and completed by 1752.","description":["The Franciscan Monastery of Deva, dedicated to St Mary, is a historic and architectural monument (LMI code HD-II-a-B-03231). It was founded in the early 18th century by monks of the Bulgarian province of the Franciscan Order, supported by the Catholics of Chiprovtsi, who emigrated en masse to Wallachia and Transylvania at the end of the 17th century. The complex was built in stages, up to 1752.","The quadrangular building follows the style of Transylvanian Franciscan monasteries, with the Baroque church attached to the south-east corner; it is built of stone and brick, with relief decoration and late-Baroque statuettes. It burned several times — in 1707, set alight by the troops of General Acton, then in 1748 and 1872 — and in 1749 the church was enlarged using material from the damaged buildings."],"facts":[{"label":"Patron","value":"St Mary"},{"label":"Style","value":"Baroque, of stone and brick"},{"label":"Fires","value":"1707, 1748, 1872"},{"label":"LMI code","value":"HD-II-a-B-03231"},{"label":"Address","value":"Strada Progresului, Deva"}]}},{"id":"cetatea-piatra-rosie","name":"Cetatea Piatra Roșie","category":{"ro":"Cetate dacică","en":"Dacian fortress"},"area":"Munții Orăștiei","townId":"bosorod","coords":[45.6024,23.147],"hasReviews":true,"season":"tot-anul","relatedIds":["traseu-gradistea-cetatea-piatra-rosie-cioclovina"],"images":["images/cetatea-piatra-rosie-zid.jpg"],"photoCredit":{"author":"Korinna","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Piatra_Rosie_WP_20170604_15_56_36_Pro_highres.jpg"},"ro":{"tagline":"Cetate dacică de piatră pe dealul Piatra Roșie, apărând dinspre vest capitala Sarmizegetusa Regia; în patrimoniul mondial UNESCO.","description":["Cetatea dacică Piatra Roșie (Luncani–Piatra Roșie) se află pe un deal de circa 832 m din satul Luncani, comuna Boșorod, în Munții Orăștiei. A fost ridicată la sfârșitul secolului I î.Hr. și folosită în secolul I d.Hr., ca parte a sistemului defensiv care proteja dinspre vest capitala dacilor, Sarmizegetusa Regia. Este una dintre cele șase fortărețe dacice din Munții Orăștiei înscrise în patrimoniul mondial UNESCO.","Construită din piatră, în tehnica dacică a zidului cu blocuri fasonate (murus dacicus), cetatea are o incintă dreptunghiulară de circa 102 × 45 m, cu turnuri la colțuri și un turn pe latura de est. S-a lucrat în două etape: întâi citadela dreptunghiulară, apoi o incintă mai largă, pentru care vârful dealului a fost nivelat. Numele vine de la piatra roșiatică a zidurilor, spre deosebire de calcarul alb din alte cetăți. Printre descoperiri se numără o sabie de fier de tip celtic, învelișul unui scut de paradă, un candelabru de bronz și un bust de bronz considerat a o înfățișa pe zeița Bendis. Cetatea a fost distrusă de romani în anul 106 d.Hr."],"facts":[{"label":"Datare","value":"sfârșitul sec. I î.Hr. – sec. I d.Hr."},{"label":"Altitudine","value":"circa 832 m (dealul Piatra Roșie)"},{"label":"Incintă","value":"circa 102 × 45 m, cu turnuri de apărare"},{"label":"Statut","value":"patrimoniu mondial UNESCO; monument istoric (cod LMI HD-I-s-A-03200)"},{"label":"Localizare","value":"satul Luncani, comuna Boșorod, Parcul Natural Grădiștea Muncelului–Cioclovina"}]},"en":{"name":"Piatra Roșie Fortress","tagline":"A Dacian stone fortress on Piatra Roșie hill, guarding the capital Sarmizegetusa Regia from the west; UNESCO World Heritage.","description":["The Dacian fortress of Piatra Roșie (Luncani–Piatra Roșie, “Red Rock”) stands on a hill of about 832 m at Luncani village, Boșorod commune, in the Orăștie Mountains. It was built at the end of the 1st century BC and used in the 1st century AD, as part of the defensive system that protected the Dacian capital, Sarmizegetusa Regia, from the west. It is one of the six Dacian fortresses of the Orăștie Mountains inscribed on the UNESCO World Heritage List.","Built of stone in the Dacian technique of dressed blocks (murus dacicus), the fortress has a rectangular enclosure of about 102 × 45 m, with towers at the corners and one on the east side. It was built in two phases: first the rectangular citadel, then a larger enclosure, for which the hilltop was levelled. The name comes from the reddish stone of the walls, unlike the white limestone of other fortresses. Finds include a Celtic-type iron sword, the covering of a parade shield, a bronze candelabrum and a bronze bust thought to represent the goddess Bendis. The fortress was destroyed by the Romans in AD 106."],"facts":[{"label":"Dating","value":"end of 1st century BC – 1st century AD"},{"label":"Altitude","value":"about 832 m (Piatra Roșie hill)"},{"label":"Enclosure","value":"about 102 × 45 m, with defensive towers"},{"label":"Status","value":"UNESCO World Heritage; historic monument (LMI code HD-I-s-A-03200)"},{"label":"Location","value":"Luncani village, Boșorod commune, Grădiștea Muncelului–Cioclovina Natural Park"}]}},{"id":"cetatea-banita","name":"Cetatea dacică Bănița","category":{"ro":"Cetate dacică","en":"Dacian fortress"},"area":"Bănița","townId":"banita","coords":[45.4517,23.3135],"hasReviews":true,"season":"tot-anul","relatedIds":["cheile-banitei"],"images":["images/cetatea-banita.jpg"],"photoCredit":{"author":"Muzeul Civilizației Dacice și Romane Deva","license":"material de promovare al instituției","source":"https://www.facebook.com/photo/?fbid=1493113089498058","sourceLabel":"Facebook"},"ro":{"tagline":"Cetate dacică pe Piatra Cetății, lângă Cheile Băniței, din patrimoniul mondial UNESCO; din 2026 se urcă pe un traseu tematic marcat.","description":["Cetatea dacică de la Bănița se află pe Piatra Cetății, la circa 902 m altitudine, lângă Cheile Băniței. Este una dintre cele șase fortărețe dacice din Munții Orăștiei care au intrat în 1999 în patrimoniul mondial UNESCO, alături de Sarmizegetusa Regia, Costești-Cetățuie, Costești-Blidaru, Piatra Roșie și Căpâlna.","Din 1 august 2026, cetatea poate fi vizitată pe traseul tematic „Cetatea Bănița”, marcat și amenajat, care traversează Cheile Băniței și continuă prin pădure, pe un drum în pantă: 570 m, 104 m diferență de nivel, dificultate medie, circa 40 de minute la urcare. Traseul a fost pus la dispoziția publicului de Muzeul Civilizației Dacice și Romane Deva, împreună cu Primăria Bănița, Parcul Natural Grădiștea Muncelului–Cioclovina, Romsilva și Salvamont Hunedoara."],"facts":[{"label":"Altitudine","value":"circa 902 m (Piatra Cetății)"},{"label":"Statut","value":"patrimoniu mondial UNESCO din 1999 (Fortărețele dacice din Munții Orăștiei)"},{"label":"Traseu tematic","value":"570 m, diferență de nivel 104 m, dificultate medie, circa 40 de minute la urcare"},{"label":"Localizare","value":"lângă Cheile Băniței, comuna Bănița"}]},"en":{"name":"Bănița Dacian Fortress","tagline":"A Dacian fortress on Piatra Cetății by the Bănița Gorge, UNESCO World Heritage; since 2026 reached by a marked themed trail.","description":["The Dacian fortress at Bănița stands on Piatra Cetății, at about 902 m altitude, next to the Bănița Gorge. It is one of the six Dacian fortresses of the Orăștie Mountains that joined the UNESCO World Heritage List in 1999, alongside Sarmizegetusa Regia, Costești-Cetățuie, Costești-Blidaru, Piatra Roșie and Căpâlna.","Since 1 August 2026 the fortress can be visited on the marked and improved “Bănița Fortress” themed trail, which crosses the Bănița Gorge and continues through the forest on a steep track: 570 m, a 104 m height difference, medium difficulty, about 40 minutes uphill. The trail was opened to the public by the Museum of Dacian and Roman Civilisation in Deva, together with Bănița town hall, the Grădiștea Muncelului–Cioclovina Natural Park, Romsilva and Salvamont Hunedoara."],"facts":[{"label":"Altitude","value":"about 902 m (Piatra Cetății)"},{"label":"Status","value":"UNESCO World Heritage since 1999 (Dacian Fortresses of the Orăștie Mountains)"},{"label":"Themed trail","value":"570 m, 104 m height difference, medium difficulty, about 40 minutes uphill"},{"label":"Location","value":"by the Bănița Gorge, Bănița commune"}]}},{"id":"castelul-pogany-pacliza","name":"Castelul Pogány din Păclișa","category":{"ro":"Castel","en":"Castle"},"area":"Totești","townId":"totesti","coords":[45.5733,22.8862],"hasReviews":false,"images":["images/totesti.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 ro","source":"https://commons.wikimedia.org/wiki/File:PăclișaHD_(6).JPG"},"ro":{"tagline":"Castel baroc cu două niveluri și 22 de camere, într-un parc cu pârâu, construit în jurul anului 1800 la 6 km de Hațeg; azi aici funcționează un spital pentru copii.","description":["Castelul din Păclișa, comuna Totești, a fost construit în stil baroc în jurul anului 1800 (secolul al XVIII-lea, cu modificări și adăugiri din secolul al XIX-lea). Are două niveluri și 22 de camere și este înconjurat de un parc cu un pârâu și alei de plimbare. Se află la circa 6 km de Hațeg și la aproximativ 15 km de Parcul Național Retezat.","După al Doilea Război Mondial, armata sovietică a ocupat castelul și a amenajat o cazarmă în incintă. Au urmat lucrări de reabilitare la începutul anilor ’90 și, din 2001, alte lucrări. Azi ansamblul găzduiește Spitalul de Neuropsihiatrie Infantilă „Dr. V. Ilea”, iar castelul servește drept sediu administrativ. Informații despre vizitare nu sunt publicate."],"facts":[{"label":"Localizare","value":"satul Păclișa, comuna Totești, la circa 6 km de Hațeg"},{"label":"Stil și epocă","value":"baroc, jurul anului 1800 (modificări în secolul al XIX-lea)"},{"label":"Cod LMI","value":"HD-II-a-A-03402 (împreună cu parcul)"},{"label":"Utilizare actuală","value":"Spitalul de Neuropsihiatrie Infantilă „Dr. V. Ilea”; vizitarea nu e documentată"}]},"en":{"name":"Pogány Castle, Păclișa","tagline":"A two-storey Baroque castle with 22 rooms, in a park with a stream, built around 1800 6 km from Hațeg; a children's hospital now operates here.","description":["The castle in Păclișa, Totești commune, was built in the Baroque style around 1800 (18th century, with 19th-century alterations and additions). It has two storeys and 22 rooms and stands in a park with a stream and walking paths. It lies about 6 km from Hațeg and roughly 15 km from the Retezat National Park.","After the Second World War the Soviet army occupied the castle and set up barracks in the grounds. Rehabilitation works followed in the early 1990s and further works from 2001. Today the complex houses the “Dr. V. Ilea” Child Neuropsychiatry Hospital, and the castle serves as its administrative seat. No visiting information is published."],"facts":[{"label":"Location","value":"Păclișa village, Totești commune, about 6 km from Hațeg"},{"label":"Style and era","value":"Baroque, around 1800 (19th-century alterations)"},{"label":"LMI code","value":"HD-II-a-A-03402 (together with the park)"},{"label":"Current use","value":"“Dr. V. Ilea” Child Neuropsychiatry Hospital; visiting is not documented"}]}},{"id":"biserica-gurasada","name":"Biserica „Sfântul Arhanghel Mihail” din Gurasada","category":{"ro":"Biserică","en":"Church"},"area":"Gurasada","townId":"gurasada","coords":[45.9508,22.5878],"hasReviews":false,"images":["images/biserica-gurasada.jpg"],"photoCredit":{"author":"Bianca Petrescu","license":"CC BY-SA 3.0 ro","source":"https://commons.wikimedia.org/wiki/File:Biserica_Sfantul_Arhanghel_Mihail,_Gurasada,_HD.jpg"},"ro":{"tagline":"Biserică de piatră cu plan în patru lobi, ridicată în mai multe etape, cu pictură murală din 1765 și o scenă a Judecății de Apoi cu aproximativ 30 de categorii de păcate.","description":["Biserica de la marginea satului Gurasada este o clădire de piatră în tradiție romanică, cu plan în patru lobi (est–vest), abside laterale semicirculare și turn prismatic deasupra centrului. Cercetările arheologice din 1977 și 1984 arată că a fost ridicată în cel puțin patru etape: nucleul inițial, datat în secolele X–XI, a fost completat în jurul anului 1300 cu pronaos și proscomidiar, iar în secolul al XIV-lea pronaosul a fost împărțit cu bolți pe stâlpi. Clopotnița cu galerie deschisă și turnuleț subțire datează din 1765, iar anexa din nord din 1820.","Pictura murală este din 1765: o inscripție de pe peretele vestic îi numește pe Ioan din Deva (pronaos) și Nicolae din Pitești (naos). În pronaos se află o Judecată de Apoi care înfățișează circa 30 de categorii de păcate, printre care nedreptăți sociale. Identitatea ctitorilor este disputată. Satul e menționat prima dată în 1292, iar biserica a fost reparată în 1668, 1905, 1915, 1928, 1960 și 1988–1994."],"facts":[{"label":"Localizare","value":"marginea satului Gurasada, județul Hunedoara"},{"label":"Etape de construcție","value":"nucleu din sec. X–XI; completări ~1300 și în sec. XIV; clopotniță 1765; anexă 1820"},{"label":"Pictură murală","value":"1765, Ioan din Deva și Nicolae din Pitești; Judecata de Apoi în pronaos"},{"label":"Cod LMI","value":"HD-II-m-A-03323"}]},"en":{"name":"Saint Archangel Michael Church, Gurasada","tagline":"A stone church with a four-lobed plan, built in several stages, with 1765 murals and a Last Judgment scene showing about 30 categories of sins.","description":["The church on the edge of Gurasada village is a stone building in the Romanesque tradition, with an east–west four-lobed plan, semicircular side apses and a prismatic tower over the centre. Archaeological research in 1977 and 1984 shows it was built in at least four stages: the original core, dated to the 10th–11th centuries, gained a narthex and prothesis around 1300, and in the 14th century the narthex was divided by vaults on pillars. The bell tower with an open gallery and slender spire dates from 1765, and the northern annex from 1820.","The murals date from 1765: an inscription on the west wall names Ioan of Deva (narthex) and Nicolae of Pitești (nave). The narthex has a Last Judgment depicting around 30 categories of sins, including social injustices. The identity of the founders is disputed. The village is first recorded in 1292, and the church was repaired in 1668, 1905, 1915, 1928, 1960 and 1988–1994."],"facts":[{"label":"Location","value":"edge of Gurasada village, Hunedoara County"},{"label":"Building stages","value":"core from the 10th–11th c.; additions around 1300 and in the 14th c.; bell tower 1765; annex 1820"},{"label":"Murals","value":"1765, Ioan of Deva and Nicolae of Pitești; Last Judgment in the narthex"},{"label":"LMI code","value":"HD-II-m-A-03323"}]}},{"id":"cetatea-rachitova","name":"Cetatea Răchitova","category":{"ro":"Cetate medievală","en":"Medieval fortress"},"area":"Răchitova","townId":"rachitova","coords":[45.6011,22.7479],"hasReviews":false,"images":["images/rachitova.jpg"],"photoCredit":{"author":"Bogdan Stanciu","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Rachitova.jpg"},"ro":{"tagline":"Ruinele unei cetăți din secolul al XIV-lea, la circa 500 m sud de satul Răchitova.","description":["Cetatea Răchitova se află pe teritoriul satului Răchitova, la aproximativ 500 m sud de sat, și datează din secolul al XIV-lea. Este monument istoric. Din ea se păstrează ruine; în fotografia de pe pagină se văd resturile unei temnițe medievale.","În aceeași comună se păstrează biserica românească din Răchitova (secolul al XV-lea), tot monument istoric. Informații despre accesul și vizitarea ruinelor nu sunt publicate."],"facts":[{"label":"Localizare","value":"la circa 500 m sud de satul Răchitova"},{"label":"Epocă","value":"secolul al XIV-lea"},{"label":"Cod LMI","value":"HD-II-m-A-03424"}]},"en":{"name":"Răchitova Fortress","tagline":"The ruins of a 14th-century fortress about 500 m south of Răchitova village.","description":["Răchitova Fortress stands on the territory of Răchitova village, about 500 m south of the village, and dates from the 14th century. It is a listed monument. Ruins survive; the photo on this page shows the remains of a medieval dungeon.","The same commune keeps the Romanian church of Răchitova (15th century), also a listed monument. No information on access to or visiting the ruins is published."],"facts":[{"label":"Location","value":"about 500 m south of Răchitova village"},{"label":"Era","value":"14th century"},{"label":"LMI code","value":"HD-II-m-A-03424"}]}}];
